CREATE OR REPLACE FUNCTION public._applied(p_version text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (SELECT 1 FROM schema_migrations WHERE version = p_version);
$$;

CREATE OR REPLACE FUNCTION public.auth_mode() RETURNS text
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE((SELECT lower(value) FROM settings WHERE key='auth.enforcement_mode'),'off');
$$;

CREATE OR REPLACE FUNCTION public.fn_auto_convert_enabled(p_conversion_type character varying) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE(lower(s.value) = 'true', false)
      FROM settings s
     WHERE s.key = CASE p_conversion_type
                       WHEN 'PACK_TO_LOOSE'  THEN 'cigarettes.auto_convert_enabled'
                       WHEN 'BOTTLE_TO_SHOT' THEN 'spirits.auto_convert_enabled'
                       ELSE 'inventory.auto_convert_unknown_type'
                   END;
$$;

CREATE OR REPLACE FUNCTION public.fn_block_cig_box_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'open_cigarette_boxes is deprecated (033).'
        USING HINT = 'Use fn_open_pack_fifo() / fn_ensure_available() instead.';
END $$;

CREATE OR REPLACE FUNCTION public.fn_block_legacy_recipe_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'menu_item_ingredients is retired (029b).'
        USING HINT = 'Write to insumos_base instead. See link_ingredient() in __init__.py.';
END $$;

CREATE OR REPLACE FUNCTION public.fn_complete_batch(p_batch_id character varying, p_actual_yield numeric, p_user character varying, p_grant_id character varying DEFAULT NULL::character varying) RETURNS TABLE(out_variance numeric, out_variance_pct numeric, out_unit_cost_cents integer, out_needs_authorization boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE b record; i record; v_new numeric; v_cost numeric := 0;
        v_pct numeric; v_warn numeric; v_unit integer;
BEGIN
    SELECT * INTO b FROM production_batches WHERE id = p_batch_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Unknown batch %', p_batch_id; END IF;
    IF b.status <> 'OPEN' THEN RAISE EXCEPTION 'Batch % is %', p_batch_id, b.status; END IF;
    IF p_actual_yield < 0 THEN RAISE EXCEPTION 'actual_yield cannot be negative'; END IF;

    v_pct := round(((p_actual_yield - b.expected_yield) / b.expected_yield) * 100, 2);
    SELECT COALESCE(pr.variance_warn_pct, 10) INTO v_warn
      FROM production_recipes pr WHERE pr.id = b.production_recipe_id;

    IF abs(v_pct) > COALESCE(v_warn, 10) AND p_grant_id IS NULL THEN
        RETURN QUERY SELECT (p_actual_yield - b.expected_yield), v_pct, NULL::integer, true;
        RETURN;
    END IF;

    FOR i IN SELECT * FROM production_batch_inputs WHERE batch_id = p_batch_id LOOP
        PERFORM 1 FROM inventory_items WHERE id = i.inventory_item_id FOR UPDATE;
        SELECT ii.stock_quantity - i.quantity_consumed INTO v_new
          FROM inventory_items ii WHERE ii.id = i.inventory_item_id;
        IF v_new < 0 THEN
            RAISE EXCEPTION 'INSUFFICIENT_INPUT: item % would go negative', i.inventory_item_id;
        END IF;
        UPDATE inventory_items SET stock_quantity = v_new, updated_at = clock_timestamp()
         WHERE id = i.inventory_item_id;
        INSERT INTO inventory_movements (id, inventory_item_id, event_type, quantity_delta,
            quantity_after, reference_id, reason, performed_by, created_at)
        VALUES (gen_random_uuid()::varchar, i.inventory_item_id, 'PRODUCTION_CONSUME',
                -i.quantity_consumed, v_new, p_batch_id,
                format('Lote produccion #%s', b.batch_number), p_user, clock_timestamp());
        v_cost := v_cost + COALESCE(i.unit_cost_cents,0) * i.quantity_consumed;
    END LOOP;

    PERFORM 1 FROM inventory_items WHERE id = b.output_item_id FOR UPDATE;
    SELECT ii.stock_quantity + p_actual_yield INTO v_new
      FROM inventory_items ii WHERE ii.id = b.output_item_id;
    UPDATE inventory_items SET stock_quantity = v_new, updated_at = clock_timestamp()
     WHERE id = b.output_item_id;

    v_unit := CASE WHEN p_actual_yield > 0 THEN round(v_cost / p_actual_yield)::integer END;

    INSERT INTO inventory_movements (id, inventory_item_id, event_type, quantity_delta,
        quantity_after, reference_id, reason, performed_by, unit_cost_cents, created_at)
    VALUES (gen_random_uuid()::varchar, b.output_item_id, 'PRODUCTION_YIELD',
            p_actual_yield, v_new, p_batch_id,
            format('Lote #%s (esperado %s, real %s)', b.batch_number, b.expected_yield, p_actual_yield),
            p_user, v_unit, clock_timestamp());

    UPDATE inventory_items SET unit_cost_cents = v_unit
     WHERE id = b.output_item_id AND v_unit IS NOT NULL;

    UPDATE production_batches
       SET status='COMPLETED', actual_yield=p_actual_yield, completed_at=clock_timestamp(),
           variance_pct=v_pct, input_cost_cents=v_cost::integer,
           output_unit_cost_cents=v_unit, grant_id=p_grant_id
     WHERE id = p_batch_id;

    RETURN QUERY SELECT (p_actual_yield - b.expected_yield), v_pct, v_unit, false;
END $$;

CREATE OR REPLACE FUNCTION public.fn_conv_no_cycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        WITH RECURSIVE reach(item_id, depth) AS (
            SELECT NEW.to_item_id, 1
            UNION ALL
            SELECT c.to_item_id, r.depth + 1
              FROM inventory_conversions c
              JOIN reach r ON c.from_item_id = r.item_id
             WHERE c.is_active AND r.depth < 10
        )
        SELECT 1 FROM reach WHERE item_id = NEW.from_item_id
    ) THEN
        RAISE EXCEPTION 'CONVERSION CYCLE: % -> % closes a loop.',
            NEW.from_item_id, NEW.to_item_id
            USING HINT = 'Conversions must be one-way (bottle -> shot, never both).';
    END IF;
    RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.fn_conversion_unit_cost(p_from_item character varying) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
    SELECT CASE WHEN c.ratio > 0
                THEN round(COALESCE(i.unit_cost_cents, 0) / c.ratio)::integer END
      FROM inventory_conversions c
      JOIN inventory_items i ON i.id = c.from_item_id
     WHERE c.from_item_id = p_from_item AND c.is_active LIMIT 1;
$$;

CREATE OR REPLACE FUNCTION public.fn_convert_stock(p_from_item character varying, p_units numeric, p_user character varying, p_reference character varying DEFAULT NULL::character varying, p_reason text DEFAULT NULL::text) RETURNS TABLE(from_new_stock numeric, to_item character varying, to_new_stock numeric, units_created numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE c record; v_from numeric; v_to numeric; v_created numeric;
BEGIN
    IF p_units <= 0 THEN
        RAISE EXCEPTION 'units must be positive, got %', p_units;
    END IF;

    SELECT * INTO c FROM inventory_conversions
     WHERE from_item_id = p_from_item AND is_active LIMIT 1;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'No active conversion defined for item %', p_from_item;
    END IF;

    -- lock both sides, lowest id first, matching check_stock_for_item's order
    PERFORM 1 FROM inventory_items
      WHERE id IN (p_from_item, c.to_item_id) ORDER BY id FOR UPDATE;

    SELECT stock_quantity INTO v_from FROM inventory_items WHERE id = p_from_item;
    IF v_from < p_units THEN
        RAISE EXCEPTION 'INSUFFICIENT_SOURCE: % has %, need %', p_from_item, v_from, p_units;
    END IF;

    v_created := floor(p_units * c.ratio * (1 - c.loss_factor));
    v_from    := v_from - p_units;
    SELECT stock_quantity + v_created INTO v_to FROM inventory_items WHERE id = c.to_item_id;

    UPDATE inventory_items SET stock_quantity = v_from, updated_at = clock_timestamp()
     WHERE id = p_from_item;
    INSERT INTO inventory_movements
       (id, inventory_item_id, event_type, quantity_delta, quantity_after,
        reference_id, reason, performed_by, created_at)
    VALUES (gen_random_uuid()::varchar, p_from_item, 'CONVERSION_OUT', -p_units, v_from,
            p_reference, COALESCE(p_reason, format('Conversion %s -> %s', p_units, v_created)),
            p_user, clock_timestamp());

    UPDATE inventory_items SET stock_quantity = v_to, updated_at = clock_timestamp()
     WHERE id = c.to_item_id;
    INSERT INTO inventory_movements
       (id, inventory_item_id, event_type, quantity_delta, quantity_after,
        reference_id, reason, performed_by, created_at)
    VALUES (gen_random_uuid()::varchar, c.to_item_id, 'CONVERSION_IN', v_created, v_to,
            p_reference, COALESCE(p_reason, format('Desde %s x %s', p_units, c.conversion_type)),
            p_user, clock_timestamp());

    RETURN QUERY SELECT v_from, c.to_item_id, v_to, v_created;
END $$;

CREATE OR REPLACE FUNCTION public.fn_count_adjustment(p_item character varying, p_counted numeric, p_user character varying, p_note text DEFAULT NULL::text) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE v_current numeric; v_delta numeric;
BEGIN
    IF p_counted < 0 THEN RAISE EXCEPTION 'counted quantity cannot be negative'; END IF;

    SELECT stock_quantity INTO v_current FROM inventory_items WHERE id = p_item FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Unknown inventory item %', p_item; END IF;

    v_delta := p_counted - v_current;
    IF v_delta = 0 THEN RETURN 0; END IF;

    UPDATE inventory_items SET stock_quantity = p_counted, updated_at = clock_timestamp()
     WHERE id = p_item;

    INSERT INTO inventory_movements
       (id, inventory_item_id, event_type, quantity_delta, quantity_after,
        reason, performed_by, created_at)
    VALUES (gen_random_uuid()::varchar, p_item, 'COUNT_ADJUSTMENT', v_delta, p_counted,
            COALESCE(p_note, 'Conteo fisico'), p_user, clock_timestamp());

    RETURN v_delta;
END $$;

CREATE OR REPLACE FUNCTION public.fn_effective_available(p_item character varying) RETURNS TABLE(available_now numeric, available_with_prep numeric, sources jsonb)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE v_now numeric := 0; v_prep numeric := 0; v_src jsonb := '[]'::jsonb; r record;
BEGIN
    FOR r IN
        WITH RECURSIVE up AS (
            SELECT i.id AS item_id, i.name, i.stock_quantity AS qty, 1::numeric AS factor, 0 AS depth
              FROM inventory_items i WHERE i.id = p_item
            UNION ALL
            SELECT src.id, src.name, src.stock_quantity,
                   u.factor * c.ratio * (1 - c.loss_factor), u.depth + 1
              FROM up u
              JOIN inventory_conversions c ON c.to_item_id = u.item_id
                                          AND c.is_active AND c.is_automatic
              JOIN inventory_items src ON src.id = c.from_item_id AND src.is_active
             WHERE u.depth < 5)
        SELECT item_id, name, qty, factor, depth FROM up
    LOOP
        v_now := v_now + (r.qty * r.factor);
        v_src := v_src || jsonb_build_object(
            'item_id', r.item_id, 'name', r.name, 'stock', r.qty, 'factor', r.factor,
            'contributes', r.qty * r.factor, 'depth', r.depth,
            'kind', CASE WHEN r.depth = 0 THEN 'own' ELSE 'convertible' END);
    END LOOP;

    SELECT COALESCE(min(floor(i.stock_quantity / ri.quantity)) * p.expected_yield, 0)
      INTO v_prep
      FROM production_recipes p
      JOIN production_recipe_inputs ri ON ri.production_recipe_id = p.id
      JOIN inventory_items i ON i.id = ri.input_item_id
     WHERE p.output_item_id = p_item AND p.is_active AND ri.quantity > 0
     GROUP BY p.expected_yield;

    RETURN QUERY SELECT v_now, v_now + COALESCE(v_prep, 0), v_src;
END $$;

CREATE OR REPLACE FUNCTION public.fn_ensure_available(p_item character varying, p_needed numeric, p_user character varying, p_reference character varying DEFAULT NULL::character varying) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE v_have numeric; v_deficit numeric; c record; v_units numeric;
BEGIN
    -- Lock the child first. The caller (inventory_svc) has already locked every
    -- row this transaction will touch, parents included, in ascending id order,
    -- so re-taking this lock is free and cannot deadlock.
    SELECT stock_quantity INTO v_have FROM inventory_items WHERE id = p_item FOR UPDATE;
    IF NOT FOUND THEN RETURN 0; END IF;
    IF v_have >= p_needed THEN RETURN 0; END IF;          -- loose stock covers it

    SELECT * INTO c FROM inventory_conversions
     WHERE to_item_id = p_item AND is_active AND is_automatic LIMIT 1;
    IF NOT FOUND THEN RETURN 0; END IF;                   -- caller reports shortage

    -- The gate is now per family, not one flag for everything.
    IF NOT fn_auto_convert_enabled(c.conversion_type) THEN RETURN 0; END IF;

    v_deficit := p_needed - v_have;
    v_units   := ceil(v_deficit / (c.ratio * (1 - c.loss_factor)));

    -- Do not open a parent that does not exist. Without this the conversion
    -- raises mid-sale instead of letting the caller report a clean shortage.
    IF (SELECT stock_quantity FROM inventory_items WHERE id = c.from_item_id) < v_units THEN
        RETURN 0;
    END IF;

    PERFORM fn_convert_stock(c.from_item_id, v_units, p_user, p_reference,
                             'Conversion automatica por venta');
    RETURN v_units;
END $$;

CREATE OR REPLACE FUNCTION public.fn_kds_events_prune() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE v_deleted integer;
BEGIN
    DELETE FROM kds_events
     WHERE acked_at IS NOT NULL
       AND created_at < clock_timestamp() - (COALESCE(
             (SELECT value::int FROM settings WHERE key='kds.event_retention_hours'), 72)
             || ' hours')::interval;
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    RETURN v_deleted;
END $$;

CREATE OR REPLACE FUNCTION public.fn_ledger_guard_movement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_mode text := ledger_mode(); v_prev numeric(12,4); v_expected numeric(12,4);
BEGIN
    IF v_mode = 'off' THEN RETURN NEW; END IF;

    IF NEW.created_at IS NULL THEN
        NEW.created_at := clock_timestamp();
    END IF;

    IF NEW.created_at < ledger_cutover() THEN RETURN NEW; END IF;

    PERFORM 1 FROM inventory_items WHERE id = NEW.inventory_item_id FOR UPDATE;

    -- ordered by seq, so movements written in the SAME transaction resolve correctly
    SELECT m.quantity_after INTO v_prev
      FROM inventory_movements m
     WHERE m.inventory_item_id = NEW.inventory_item_id
       AND m.quantity_after IS NOT NULL
       AND m.created_at IS NOT NULL
       AND m.created_at >= ledger_cutover()
     ORDER BY m.seq DESC
     LIMIT 1;

    IF v_prev IS NULL THEN
        -- First post-cutover movement. stock_quantity ALREADY reflects it.
        IF NEW.quantity_after IS NULL THEN
            SELECT i.stock_quantity INTO NEW.quantity_after
              FROM inventory_items i WHERE i.id = NEW.inventory_item_id;
        END IF;
        RETURN NEW;
    END IF;

    v_expected := v_prev + NEW.quantity_delta;

    IF NEW.quantity_after IS NULL THEN
        NEW.quantity_after := v_expected;
        RETURN NEW;
    END IF;

    IF NEW.quantity_after <> v_expected THEN
        IF v_mode = 'enforce' THEN
            RAISE EXCEPTION
                'LEDGER CHAIN BREAK on item %: quantity_after=% but previous(%) + delta(%) = %',
                NEW.inventory_item_id, NEW.quantity_after, v_prev, NEW.quantity_delta, v_expected
                USING HINT = 'Stock changed without a matching movement row.';
        ELSE
            INSERT INTO ledger_violations
                (violation_type, source, inventory_item_id, movement_id,
                 expected_value, actual_value, context)
            VALUES ('CHAIN_BREAK','TRIGGER', NEW.inventory_item_id, NEW.id,
                    v_expected, NEW.quantity_after,
                    jsonb_build_object('event_type', NEW.event_type, 'delta', NEW.quantity_delta,
                                       'prev_after', v_prev, 'seq', NEW.seq,
                                       'performed_by', NEW.performed_by,
                                       'reference_id', NEW.reference_id));
        END IF;
    END IF;

    RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.fn_ledger_scan_chain(p_since timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(inventory_item_id character varying, item_name character varying, movement_id character varying, seq bigint, occurred_at timestamp with time zone, prev_after numeric, delta numeric, recorded_after numeric, expected_after numeric)
    LANGUAGE sql STABLE
    AS $$
    WITH chain AS (
        SELECT m.inventory_item_id, m.id, m.seq, m.created_at, m.quantity_delta, m.quantity_after,
               lag(m.quantity_after) OVER (PARTITION BY m.inventory_item_id ORDER BY m.seq) AS prev_after
          FROM inventory_movements m
         WHERE m.created_at IS NOT NULL
           AND m.created_at >= COALESCE(p_since, ledger_cutover())
           AND m.quantity_after IS NOT NULL)
    SELECT c.inventory_item_id, i.name, c.id, c.seq, c.created_at,
           c.prev_after, c.quantity_delta, c.quantity_after, c.prev_after + c.quantity_delta
      FROM chain c JOIN inventory_items i ON i.id = c.inventory_item_id
     WHERE c.prev_after IS NOT NULL
       AND c.quantity_after <> c.prev_after + c.quantity_delta;
$$;

CREATE OR REPLACE FUNCTION public.fn_ledger_verify_stock() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_mode text := ledger_mode(); v_latest numeric(12,4);
        v_current numeric(12,4); v_name varchar(100); v_any boolean;
BEGIN
    IF v_mode = 'off' THEN RETURN NULL; END IF;

    -- CRITICAL: in a DEFERRED constraint trigger, NEW is the row image from the
    -- time of the UPDATE, not the committed state. update_item_quantity does
    -- reverse-then-reconsume, so it updates stock TWICE and this trigger fires
    -- twice -- the earlier firing carries a stale NEW. Verified empirically on
    -- 2026-08-07: a 1->3 quantity change produced a false STOCK_MISMATCH
    -- (expected 21, NEW said 24). In enforce mode that would abort every
    -- quantity change in the POS. Always re-read the current row.
    SELECT stock_quantity, name INTO v_current, v_name
      FROM inventory_items WHERE id = NEW.id;
    IF NOT FOUND THEN RETURN NULL; END IF;   -- row removed later in the txn

    SELECT m.quantity_after INTO v_latest
      FROM inventory_movements m
     WHERE m.inventory_item_id = NEW.id
       AND m.quantity_after IS NOT NULL
       AND m.created_at IS NOT NULL
       AND m.created_at >= ledger_cutover()
     ORDER BY m.seq DESC
     LIMIT 1;

    IF v_latest IS NULL THEN
        SELECT EXISTS (SELECT 1 FROM inventory_movements WHERE inventory_item_id = NEW.id)
          INTO v_any;

        -- Stock exists but the item has NO movements whatsoever -> unbacked stock
        IF NOT v_any AND v_current <> 0 THEN
            IF v_mode = 'enforce' THEN
                RAISE EXCEPTION 'STOCK WITHOUT LEDGER: % has stock % and no movements',
                    v_name, v_current
                    USING HINT = 'Create stock via an OPENING_STOCK movement.';
            ELSE
                INSERT INTO ledger_violations
                    (violation_type, source, inventory_item_id, expected_value, actual_value, context)
                VALUES ('STOCK_WITHOUT_LEDGER','TRIGGER', NEW.id, 0, v_current,
                        jsonb_build_object('item_name', v_name, 'tg_op', TG_OP));
            END IF;
        END IF;
        RETURN NULL;   -- pre-cutover-only history: correctly skipped
    END IF;

    IF v_current <> v_latest THEN
        IF v_mode = 'enforce' THEN
            RAISE EXCEPTION 'STOCK/LEDGER MISMATCH on %: stock=% but latest movement=%',
                v_name, v_current, v_latest
                USING HINT = 'stock_quantity changed without a movement row.';
        ELSE
            INSERT INTO ledger_violations
                (violation_type, source, inventory_item_id, expected_value, actual_value, context)
            VALUES ('STOCK_MISMATCH','TRIGGER', NEW.id, v_latest, v_current,
                    jsonb_build_object('item_name', v_name, 'tg_op', TG_OP));
        END IF;
    END IF;

    RETURN NULL;
END $$;

CREATE OR REPLACE FUNCTION public.fn_line_item_bump_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.quantity         IS DISTINCT FROM OLD.quantity
       OR NEW.status        IS DISTINCT FROM OLD.status
       OR NEW.unit_price_cents IS DISTINCT FROM OLD.unit_price_cents THEN
        NEW.version := COALESCE(OLD.version, 1) + 1;
    END IF;
    RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.fn_menu_item_max_sellable(p_menu_item character varying) RETURNS TABLE(max_sellable integer, limiting_factor text, limiting_item text)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE v_max integer := 999; r record; v_avail numeric; v_can integer;
        v_kind text; v_item text;
BEGIN
    FOR r IN SELECT b.inventory_item_id, b.quantity, ii.name
               FROM insumos_base b JOIN inventory_items ii ON ii.id = b.inventory_item_id
              WHERE b.menu_item_id = p_menu_item AND b.quantity > 0
    LOOP
        SELECT a.available_now INTO v_avail FROM fn_effective_available(r.inventory_item_id) a;
        v_can := floor(v_avail / r.quantity)::integer;
        IF v_can < v_max THEN v_max := v_can; v_kind := 'INGREDIENT'; v_item := r.name; END IF;
    END LOOP;

    FOR r IN SELECT o.group_name, o.min_selections, o.allow_multiple,
                    count(*) FILTER (WHERE o.is_available) AS opts,
                    sum(o.max_units) AS units
               FROM fn_option_availability(p_menu_item, 1) o
              WHERE o.is_mandatory
              GROUP BY o.group_name, o.min_selections, o.allow_multiple
    LOOP
        IF r.allow_multiple THEN
            v_can := floor(COALESCE(r.units,0) / GREATEST(r.min_selections,1))::integer;
        ELSE
            v_can := CASE WHEN r.opts >= r.min_selections THEN 999 ELSE 0 END;
        END IF;
        IF v_can < v_max THEN v_max := v_can; v_kind := 'MODIFIER_GROUP'; v_item := r.group_name; END IF;
    END LOOP;

    IF v_max = 999 THEN v_kind := NULL; v_item := NULL; END IF;
    RETURN QUERY SELECT GREATEST(v_max,0), v_kind, v_item;
END $$;

CREATE OR REPLACE FUNCTION public.fn_normalize_name() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.name IS NOT NULL THEN
        NEW.name := regexp_replace(btrim(NEW.name), '\s+', ' ', 'g');
    END IF;
    RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.fn_open_pack(p_pack_item character varying, p_user character varying, p_packs numeric DEFAULT 1, p_reference character varying DEFAULT NULL::character varying) RETURNS TABLE(packs_remaining numeric, loose_item character varying, loose_total numeric, loose_added numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE r record;
BEGIN
    IF p_packs <= 0 THEN RAISE EXCEPTION 'packs must be positive'; END IF;

    SELECT * INTO r FROM fn_convert_stock(
        p_pack_item, p_packs, p_user, p_reference,
        format('Apertura manual de %s cajetilla(s)', p_packs));

    RETURN QUERY SELECT r.from_new_stock, r.to_item, r.to_new_stock, r.units_created;
END $$;

CREATE OR REPLACE FUNCTION public.fn_open_pack_fifo(p_pack_item character varying, p_user character varying, p_reference character varying DEFAULT NULL::character varying) RETURNS TABLE(lot_id character varying, units_per_pack numeric, packs_remaining numeric, loose_total numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE l record; c record; v_loose numeric; v_packs numeric; r record;
BEGIN
    SELECT * INTO c FROM inventory_conversions
     WHERE from_item_id = p_pack_item AND is_active LIMIT 1;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'No conversion defined for %', p_pack_item;
    END IF;

    -- Table columns MUST be qualified: RETURNS TABLE puts packs_remaining and
    -- units_per_pack in scope as PL/pgSQL variables, so an unqualified reference
    -- is ambiguous and raises at runtime.
    SELECT * INTO l FROM inventory_pack_lots pl
     WHERE pl.inventory_item_id = p_pack_item AND pl.packs_remaining > 0
     ORDER BY pl.received_at, pl.id
     FOR UPDATE SKIP LOCKED LIMIT 1;

    -- No lot on record: fall back to the item-level ratio.
    IF l.id IS NULL THEN
        FOR r IN SELECT * FROM fn_convert_stock(p_pack_item, 1, p_user, p_reference,
                                'Apertura (sin lote; ratio por defecto)') LOOP
            RETURN QUERY SELECT NULL::varchar, c.ratio, r.from_new_stock, r.to_new_stock;
        END LOOP;
        RETURN;
    END IF;

    PERFORM 1 FROM inventory_items WHERE id IN (p_pack_item, c.to_item_id)
     ORDER BY id FOR UPDATE;

    SELECT stock_quantity INTO v_packs FROM inventory_items WHERE id = p_pack_item;
    IF v_packs < 1 THEN
        RAISE EXCEPTION 'INSUFFICIENT_SOURCE: % has % packs', p_pack_item, v_packs;
    END IF;
    v_packs := v_packs - 1;
    SELECT stock_quantity + l.units_per_pack INTO v_loose
      FROM inventory_items WHERE id = c.to_item_id;

    UPDATE inventory_items SET stock_quantity = v_packs, updated_at = clock_timestamp()
     WHERE id = p_pack_item;
    INSERT INTO inventory_movements (id, inventory_item_id, event_type, quantity_delta,
        quantity_after, reference_id, reason, performed_by, created_at)
    VALUES (gen_random_uuid()::varchar, p_pack_item, 'CONVERSION_OUT', -1, v_packs,
            p_reference, format('Apertura lote %s (%s cig/cajetilla)', l.id, l.units_per_pack),
            p_user, clock_timestamp());

    UPDATE inventory_items SET stock_quantity = v_loose, updated_at = clock_timestamp()
     WHERE id = c.to_item_id;
    INSERT INTO inventory_movements (id, inventory_item_id, event_type, quantity_delta,
        quantity_after, reference_id, reason, performed_by, created_at)
    VALUES (gen_random_uuid()::varchar, c.to_item_id, 'CONVERSION_IN', l.units_per_pack,
            v_loose, p_reference, format('Lote %s', l.id), p_user, clock_timestamp());

    UPDATE inventory_pack_lots
       SET packs_remaining = inventory_pack_lots.packs_remaining - 1
     WHERE inventory_pack_lots.id = l.id;

    RETURN QUERY SELECT l.id, l.units_per_pack, v_packs, v_loose;
END $$;

CREATE OR REPLACE FUNCTION public.fn_option_availability(p_menu_item_id character varying, p_quantity integer DEFAULT 1) RETURNS TABLE(group_id character varying, group_name character varying, is_mandatory boolean, min_selections integer, max_selections integer, allow_multiple boolean, modifier_id character varying, modifier_name character varying, max_units numeric, is_available boolean, limiting_item character varying)
    LANGUAGE sql STABLE
    AS $$
WITH recipe_need AS (
    SELECT b.inventory_item_id, sum(b.quantity) * p_quantity AS need
      FROM insumos_base b WHERE b.menu_item_id = p_menu_item_id GROUP BY 1),
remaining AS (
    SELECT i.id, GREATEST(i.stock_quantity - COALESCE(rn.need, 0), 0) AS avail
      FROM inventory_items i
      LEFT JOIN recipe_need rn ON rn.inventory_item_id = i.id)
SELECT g.id, g.name, g.is_mandatory, g.min_selections, g.max_selections, g.allow_multiple,
       m.id, m.name,
       CASE WHEN m.deducts_no_inventory THEN 9999
            ELSE COALESCE(min(floor(rem.avail / NULLIF(r.quantity,0) / p_quantity)), 9999)
       END,
       CASE WHEN m.deducts_no_inventory THEN true
            ELSE COALESCE(min(floor(rem.avail / NULLIF(r.quantity,0) / p_quantity)), 9999) >= 1
       END,
       (array_agg(ii.name ORDER BY floor(rem.avail / NULLIF(r.quantity,0)) NULLS LAST))[1]
  FROM menu_item_modifier_groups mg
  JOIN modifier_groups g ON g.id = mg.modifier_group_id
  JOIN modifiers m       ON m.modifier_group_id = g.id AND m.is_active
  LEFT JOIN modifier_inventory_rules r ON r.modifier_id = m.id
  LEFT JOIN remaining rem              ON rem.id = r.inventory_item_id
  LEFT JOIN inventory_items ii         ON ii.id = r.inventory_item_id
 WHERE mg.menu_item_id = p_menu_item_id
 GROUP BY g.id, g.name, g.is_mandatory, g.min_selections, g.max_selections,
          g.allow_multiple, m.id, m.name, m.deducts_no_inventory;
$$;

CREATE OR REPLACE FUNCTION public.fn_pin_is_locked(p_user character varying, p_device character varying) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT count(*) >= COALESCE(
             (SELECT value::int FROM settings WHERE key='auth.pin_max_failures'), 5)
      FROM pin_attempts
     WHERE NOT succeeded
       AND (requested_by = p_user OR (p_device IS NOT NULL AND device_id = p_device))
       AND attempted_at > clock_timestamp() - (COALESCE(
             (SELECT value::int FROM settings WHERE key='auth.pin_lockout_seconds'), 300)
             || ' seconds')::interval;
$$;

CREATE OR REPLACE FUNCTION public.fn_prevent_negative_stock() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_mode text;
BEGIN
    IF NEW.stock_quantity >= 0 THEN RETURN NEW; END IF;
    SELECT COALESCE(lower(value),'warn') INTO v_mode
      FROM settings WHERE key='inventory.negative_stock_mode';
    IF v_mode = 'block' THEN
        RAISE EXCEPTION 'NEGATIVE STOCK blocked: % would go to %', NEW.name, NEW.stock_quantity
            USING HINT = 'Oversell prevented. Verify the physical count.';
    ELSIF v_mode = 'warn' THEN
        INSERT INTO ledger_violations
            (violation_type, source, inventory_item_id, expected_value, actual_value, context)
        VALUES ('NEGATIVE_STOCK','TRIGGER', NEW.id, 0, NEW.stock_quantity,
                jsonb_build_object('item_name', NEW.name, 'tg_op', TG_OP,
                                   'previous', CASE WHEN TG_OP='UPDATE'
                                                    THEN OLD.stock_quantity END));
    END IF;
    RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.fn_product_availability(p_menu_item_id character varying, p_quantity integer DEFAULT 1) RETURNS TABLE(is_sellable boolean, blocking_reason text, blocking_detail text)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE r record; v_short text;
BEGIN
    SELECT string_agg(ii.name || ' (' || i.stock_quantity || '/' ||
                      (b.quantity * p_quantity) || ')', ', ') INTO v_short
      FROM insumos_base b
      JOIN inventory_items i  ON i.id = b.inventory_item_id
      JOIN inventory_items ii ON ii.id = b.inventory_item_id
     WHERE b.menu_item_id = p_menu_item_id
       AND i.stock_quantity < b.quantity * p_quantity;

    IF v_short IS NOT NULL THEN
        RETURN QUERY SELECT false, 'INGREDIENT_OUT_OF_STOCK', v_short; RETURN;
    END IF;

    FOR r IN
        SELECT group_name, min_selections, allow_multiple,
               count(*) FILTER (WHERE is_available) AS options_available,
               sum(max_units)                       AS total_units
          FROM fn_option_availability(p_menu_item_id, p_quantity)
         WHERE is_mandatory
         GROUP BY group_name, min_selections, allow_multiple
    LOOP
        IF r.allow_multiple THEN
            IF COALESCE(r.total_units,0) < r.min_selections THEN
                RETURN QUERY SELECT false, 'GROUP_INSUFFICIENT_UNITS',
                    format('%s: %s de %s unidades', r.group_name,
                           COALESCE(r.total_units,0), r.min_selections);
                RETURN;
            END IF;
        ELSE
            IF r.options_available < r.min_selections THEN
                RETURN QUERY SELECT false, 'GROUP_NO_OPTIONS',
                    format('%s: %s de %s opciones con stock', r.group_name,
                           r.options_available, r.min_selections);
                RETURN;
            END IF;
        END IF;
    END LOOP;

    RETURN QUERY SELECT true, NULL::text, NULL::text;
END $$;

CREATE OR REPLACE FUNCTION public.fn_recipe_unit_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_base varchar(50);
BEGIN
    SELECT base_unit_key INTO v_base FROM inventory_items WHERE id = NEW.inventory_item_id;
    IF NEW.deduction_unit_key IS NOT NULL AND NEW.deduction_unit_key <> v_base THEN
        RAISE EXCEPTION 'UNIT MISMATCH: recipe deducts % but the item is stocked in %',
            NEW.deduction_unit_key, v_base
            USING HINT = 'unit_catalog has no conversion factors. Use the base unit.';
    END IF;
    NEW.deduction_unit_key := COALESCE(NEW.deduction_unit_key, v_base);
    RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.ledger_cutover() RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE((SELECT value::timestamptz FROM settings WHERE key = 'ledger.cutover_at'),
                    '2026-06-01T00:00:00-06:00'::timestamptz);
$$;

CREATE OR REPLACE FUNCTION public.ledger_mode() RETURNS text
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE((SELECT lower(value) FROM settings WHERE key='ledger.enforcement_mode'),'off');
$$;

-- --------------------------------------------------------------------------
-- Views (48)
-- --------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.v_audit_timeline AS
 SELECT 'AUDIT'::text AS source,
    a.created_at AS occurred_at,
    a.action AS event,
    a.entity_type,
    a.entity_id,
    u.name AS actor,
    NULL::character varying AS approver,
    a.before_state,
    a.after_state,
    a.reason,
    a.ip_address,
    a.device_id,
    a.location,
    NULL::numeric AS quantity_delta,
    NULL::integer AS value_cents
   FROM (public.audit_log a
     LEFT JOIN public.users u ON (((u.id)::text = (a.user_id)::text)))
UNION ALL
 SELECT 'INVENTORY'::text AS source,
    m.created_at AS occurred_at,
    m.event_type AS event,
    'inventory_item'::character varying AS entity_type,
    m.inventory_item_id AS entity_id,
    u.name AS actor,
    NULL::character varying AS approver,
    NULL::json AS before_state,
    (jsonb_build_object('quantity_after', m.quantity_after))::json AS after_state,
    m.reason,
    m.ip_address,
    m.device_id,
    m.location,
    m.quantity_delta,
    m.unit_cost_cents AS value_cents
   FROM (public.inventory_movements m
     LEFT JOIN public.users u ON (((u.id)::text = (m.performed_by)::text)))
UNION ALL
 SELECT 'OVERRIDE'::text AS source,
    o.created_at AS occurred_at,
    o.action_code AS event,
    o.target_type AS entity_type,
    o.target_id AS entity_id,
    ur.name AS actor,
    ua.name AS approver,
    (o.before_state)::json AS before_state,
    (o.after_state)::json AS after_state,
    COALESCE(o.reason_text, (o.reason_code)::text) AS reason,
    o.ip_address,
    o.device_id,
    o.location,
    NULL::numeric AS quantity_delta,
    o.value_delta_cents AS value_cents
   FROM ((public.authorization_overrides o
     JOIN public.users ur ON (((ur.id)::text = (o.requested_by)::text)))
     JOIN public.users ua ON (((ua.id)::text = (o.authorized_by)::text)))
UNION ALL
 SELECT 'VIOLATION'::text AS source,
    v.detected_at AS occurred_at,
    v.violation_type AS event,
    'inventory_item'::character varying AS entity_type,
    v.inventory_item_id AS entity_id,
    NULL::character varying AS actor,
    NULL::character varying AS approver,
    NULL::json AS before_state,
    (v.context)::json AS after_state,
    v.resolution_note AS reason,
    NULL::character varying AS ip_address,
    NULL::character varying AS device_id,
    NULL::character varying AS location,
    v.drift AS quantity_delta,
    NULL::integer AS value_cents
   FROM public.ledger_violations v
UNION ALL
 SELECT 'PRODUCTION'::text AS source,
    b.completed_at AS occurred_at,
    'PRODUCTION_BATCH'::character varying AS event,
    'inventory_item'::character varying AS entity_type,
    b.output_item_id AS entity_id,
    u.name AS actor,
    NULL::character varying AS approver,
    NULL::json AS before_state,
    (jsonb_build_object('expected', b.expected_yield, 'actual', b.actual_yield, 'variance_pct', b.variance_pct))::json AS after_state,
    b.notes AS reason,
    NULL::character varying AS ip_address,
    NULL::character varying AS device_id,
    NULL::character varying AS location,
    b.variance AS quantity_delta,
    b.input_cost_cents AS value_cents
   FROM (public.production_batches b
     JOIN public.users u ON (((u.id)::text = (b.produced_by)::text)))
  WHERE ((b.status)::text = 'COMPLETED'::text);

CREATE OR REPLACE VIEW public.v_authorization_overrides_daily AS
 SELECT (date_trunc('day'::text, o.created_at))::date AS business_date,
    o.action_code,
    a.category,
    a.description_es,
    u_req.name AS requested_by_name,
    u_auth.name AS authorized_by_name,
    count(*) AS override_count,
    sum(COALESCE(o.value_delta_cents, 0)) AS total_value_delta_cents,
    count(*) FILTER (WHERE ((o.outcome)::text = 'WARN_ONLY'::text)) AS unauthorized_warn_count
   FROM (((public.authorization_overrides o
     JOIN public.users u_req ON (((u_req.id)::text = (o.requested_by)::text)))
     JOIN public.users u_auth ON (((u_auth.id)::text = (o.authorized_by)::text)))
     LEFT JOIN public.authorized_actions a ON (((a.action_code)::text = (o.action_code)::text)))
  GROUP BY ((date_trunc('day'::text, o.created_at))::date), o.action_code, a.category, a.description_es, u_req.name, u_auth.name;

CREATE OR REPLACE VIEW public.v_bola8_anomalias_operativas AS
 SELECT 'VOID_LINEA'::text AS tipo,
    li.id AS referencia_id,
    t.id AS ticket_id,
    ((COALESCE(li.voided_at, t.closed_at) AT TIME ZONE 'America/Mexico_City'::text))::date AS fecha_mx,
    li.voided_at AS ocurrido_en,
    COALESCE(li.item_name, mi.name) AS detalle,
    li.void_reason AS motivo,
    u.name AS usuario,
    u.role AS rol_usuario,
    (round((((li.quantity * li.unit_price_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS monto_mxn
   FROM (((public.ticket_line_items li
     JOIN public.tickets t ON (((t.id)::text = (li.ticket_id)::text)))
     LEFT JOIN public.menu_items mi ON (((mi.id)::text = (li.menu_item_id)::text)))
     LEFT JOIN public.users u ON (((u.id)::text = (li.voided_by)::text)))
  WHERE ((li.voided_at IS NOT NULL) OR ((COALESCE(li.status, ''::character varying))::text = 'VOIDED'::text))
UNION ALL
 SELECT 'TICKET_REABIERTO'::text AS tipo,
    t.id AS referencia_id,
    t.id AS ticket_id,
    ((COALESCE(t.reopened_at, t.closed_at) AT TIME ZONE 'America/Mexico_City'::text))::date AS fecha_mx,
    t.reopened_at AS ocurrido_en,
    'Ticket reabierto tras cierre'::character varying AS detalle,
    t.notes AS motivo,
    u.name AS usuario,
    u.role AS rol_usuario,
    (round(((COALESCE(t.total_cents, 0))::numeric / (100)::numeric), 2))::numeric(18,2) AS monto_mxn
   FROM (public.tickets t
     LEFT JOIN public.users u ON (((u.id)::text = (t.reopened_by)::text)))
  WHERE (COALESCE(t.was_reopened, false) = true)
UNION ALL
 SELECT 'DESCUENTO_MANUAL'::text AS tipo,
    t.id AS referencia_id,
    t.id AS ticket_id,
    ((t.closed_at AT TIME ZONE 'America/Mexico_City'::text))::date AS fecha_mx,
    t.closed_at AS ocurrido_en,
    ((('Descuento manual '::text || (COALESCE(t.manual_discount_pct, 0))::text) || '%'::text))::character varying AS detalle,
    t.notes AS motivo,
    u.name AS usuario,
    u.role AS rol_usuario,
    (round(((COALESCE(t.discount_cents, 0))::numeric / (100)::numeric), 2))::numeric(18,2) AS monto_mxn
   FROM (public.tickets t
     LEFT JOIN public.users u ON (((u.id)::text = (t.closed_by)::text)))
  WHERE ((COALESCE(t.manual_discount_pct, 0) > 0) AND ((t.status)::text = 'CLOSED'::text) AND (t.closed_at IS NOT NULL))
UNION ALL
 SELECT 'EDITADO_POST_CIERRE'::text AS tipo,
    t.id AS referencia_id,
    t.id AS ticket_id,
    ((t.closed_at AT TIME ZONE 'America/Mexico_City'::text))::date AS fecha_mx,
    t.closed_at AS ocurrido_en,
    'Ticket editado después del cierre'::character varying AS detalle,
    t.notes AS motivo,
    u.name AS usuario,
    u.role AS rol_usuario,
    (round(((COALESCE(t.total_cents, 0))::numeric / (100)::numeric), 2))::numeric(18,2) AS monto_mxn
   FROM (public.tickets t
     LEFT JOIN public.users u ON (((u.id)::text = (t.closed_by)::text)))
  WHERE ((COALESCE(t.edited_after_close, false) = true) AND ((t.status)::text = 'CLOSED'::text) AND (t.closed_at IS NOT NULL));

CREATE OR REPLACE VIEW public.v_bola8_billar_por_mesa AS
 SELECT pts.resource_id,
    r.code AS mesa_codigo,
    r.name AS mesa_nombre,
    ((t.closed_at AT TIME ZONE 'America/Mexico_City'::text))::date AS fecha_mx,
    (EXTRACT(isodow FROM (t.closed_at AT TIME ZONE 'America/Mexico_City'::text)))::integer AS dia_semana_iso,
    count(*) AS sesiones,
    count(DISTINCT pts.ticket_id) AS tickets,
    sum(COALESCE(pts.duration_seconds, 0)) AS segundos,
    (round(((sum(COALESCE(pts.duration_seconds, 0)))::numeric / (3600)::numeric), 2))::numeric(18,2) AS horas,
    (round(((sum(COALESCE(pts.promo_free_seconds, 0)))::numeric / (60)::numeric), 2))::numeric(18,2) AS minutos_gratis_promo,
    sum(COALESCE(pts.charge_cents, 0)) AS ingreso_cents,
    (round(((sum(COALESCE(pts.charge_cents, 0)))::numeric / (100)::numeric), 2))::numeric(18,2) AS ingreso_mxn,
        CASE
            WHEN (sum(COALESCE(pts.duration_seconds, 0)) > 0) THEN (round((((sum(COALESCE(pts.charge_cents, 0)))::numeric / (100)::numeric) / ((sum(COALESCE(pts.duration_seconds, 0)))::numeric / (3600)::numeric)), 2))::numeric(18,2)
            ELSE NULL::numeric
        END AS ingreso_por_hora_mxn,
    count(*) FILTER (WHERE pts.is_manual_edit) AS sesiones_editadas
   FROM ((public.pool_timer_sessions pts
     JOIN public.resources r ON (((r.id)::text = (pts.resource_id)::text)))
     JOIN public.tickets t ON (((t.id)::text = (pts.ticket_id)::text)))
  WHERE (((t.status)::text = 'CLOSED'::text) AND (t.closed_at IS NOT NULL) AND (pts.cancelled_at IS NULL) AND ((COALESCE(pts.status, ''::character varying))::text <> 'CANCELLED'::text))
  GROUP BY pts.resource_id, r.code, r.name, (((t.closed_at AT TIME ZONE 'America/Mexico_City'::text))::date), ((EXTRACT(isodow FROM (t.closed_at AT TIME ZONE 'America/Mexico_City'::text)))::integer);

CREATE OR REPLACE VIEW public.v_bola8_lineas_venta AS
 WITH modifier_totals AS (
         SELECT line_item_modifiers.line_item_id,
            (sum(COALESCE(line_item_modifiers.price_cents, 0)))::integer AS modifier_cents
           FROM public.line_item_modifiers
          GROUP BY line_item_modifiers.line_item_id
        ), cost_totals AS (
         SELECT sale_item_costs.ticket_line_item_id,
            (sum(COALESCE(sale_item_costs.total_cost_cents, 0)))::integer AS total_cost_cents,
            (round(sum(COALESCE(sale_item_costs.quantity_deducted, (0)::numeric)), 2))::numeric(18,2) AS quantity_deducted
           FROM public.sale_item_costs
          GROUP BY sale_item_costs.ticket_line_item_id
        ), raw_lines AS (
         SELECT t.id AS ticket_id,
            t.closed_at,
            ((t.closed_at AT TIME ZONE 'America/Mexico_City'::text))::date AS fecha_mx,
            (EXTRACT(isodow FROM (t.closed_at AT TIME ZONE 'America/Mexico_City'::text)))::integer AS dia_semana_iso,
            (EXTRACT(hour FROM (t.closed_at AT TIME ZONE 'America/Mexico_City'::text)))::integer AS hora_mx,
            t.ticket_type,
            t.payment_type,
            t.payment_type_2,
            COALESCE(t.discount_cents, 0) AS ticket_discount_cents,
            li.id AS line_item_id,
            li.menu_item_id,
            COALESCE(li.item_name, mi.name) AS producto,
            COALESCE(mc.name, 'Sin categoria'::character varying) AS categoria,
            li.quantity,
            li.unit_price_cents,
            COALESCE(mt.modifier_cents, 0) AS modifier_cents,
            COALESCE(ct.total_cost_cents, 0) AS total_cost_cents,
            (COALESCE(ct.quantity_deducted, (0)::numeric))::numeric(18,2) AS quantity_deducted,
            ((li.quantity * li.unit_price_cents) + COALESCE(mt.modifier_cents, 0)) AS gross_line_cents,
            sum(((li.quantity * li.unit_price_cents) + COALESCE(mt.modifier_cents, 0))) OVER (PARTITION BY t.id) AS ticket_items_gross_cents
           FROM (((((public.tickets t
             JOIN public.ticket_line_items li ON (((li.ticket_id)::text = (t.id)::text)))
             LEFT JOIN public.menu_items mi ON (((mi.id)::text = (li.menu_item_id)::text)))
             LEFT JOIN public.menu_categories mc ON (((mc.id)::text = (mi.category_id)::text)))
             LEFT JOIN modifier_totals mt ON (((mt.line_item_id)::text = (li.id)::text)))
             LEFT JOIN cost_totals ct ON (((ct.ticket_line_item_id)::text = (li.id)::text)))
          WHERE (((t.status)::text = 'CLOSED'::text) AND (t.closed_at IS NOT NULL) AND ((COALESCE(li.status, ''::character varying))::text <> 'VOIDED'::text) AND (li.voided_at IS NULL))
        ), calculated AS (
         SELECT raw_lines.ticket_id,
            raw_lines.closed_at,
            raw_lines.fecha_mx,
            raw_lines.dia_semana_iso,
            raw_lines.hora_mx,
            raw_lines.ticket_type,
            raw_lines.payment_type,
            raw_lines.payment_type_2,
            raw_lines.ticket_discount_cents,
            raw_lines.line_item_id,
            raw_lines.menu_item_id,
            raw_lines.producto,
            raw_lines.categoria,
            raw_lines.quantity,
            raw_lines.unit_price_cents,
            raw_lines.modifier_cents,
            raw_lines.total_cost_cents,
            raw_lines.quantity_deducted,
            raw_lines.gross_line_cents,
            raw_lines.ticket_items_gross_cents,
                CASE
                    WHEN (raw_lines.ticket_items_gross_cents > 0) THEN (round((((raw_lines.ticket_discount_cents)::numeric * (raw_lines.gross_line_cents)::numeric) / (raw_lines.ticket_items_gross_cents)::numeric)))::integer
                    ELSE 0
                END AS allocated_discount_cents
           FROM raw_lines
        )
 SELECT calculated.ticket_id,
    calculated.closed_at,
    calculated.fecha_mx,
    calculated.dia_semana_iso,
    calculated.hora_mx,
    calculated.ticket_type,
    calculated.payment_type,
    calculated.payment_type_2,
    calculated.ticket_discount_cents,
    calculated.line_item_id,
    calculated.menu_item_id,
    calculated.producto,
    calculated.categoria,
    calculated.quantity,
    calculated.unit_price_cents,
    calculated.modifier_cents,
    calculated.total_cost_cents,
    calculated.quantity_deducted,
    calculated.gross_line_cents,
    calculated.ticket_items_gross_cents,
    calculated.allocated_discount_cents,
    (calculated.gross_line_cents - calculated.allocated_discount_cents) AS net_sales_cents,
    ((calculated.gross_line_cents - calculated.allocated_discount_cents) - calculated.total_cost_cents) AS gross_profit_cents,
    (round(((calculated.gross_line_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS gross_line_mxn,
    (round((((calculated.gross_line_cents - calculated.allocated_discount_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS net_sales_mxn,
    (round(((calculated.total_cost_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS costo_mxn,
    (round(((((calculated.gross_line_cents - calculated.allocated_discount_cents) - calculated.total_cost_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS utilidad_mxn
   FROM calculated;

CREATE OR REPLACE VIEW public.v_bola8_cobertura_costo AS
 WITH exposicion AS (
         SELECT DISTINCT sale_item_costs.inventory_item_id,
            sale_item_costs.ticket_line_item_id
           FROM public.sale_item_costs
        ), rev AS (
         SELECT e.inventory_item_id,
            sum(l.net_sales_cents) AS ventas_expuestas_cents,
            count(*) AS lineas_expuestas,
            max(l.fecha_mx) AS ultima_venta
           FROM (exposicion e
             JOIN public.v_bola8_lineas_venta l ON (((l.line_item_id)::text = (e.ticket_line_item_id)::text)))
          GROUP BY e.inventory_item_id
        )
 SELECT ii.id AS inventory_item_id,
    ii.name AS insumo,
    ii.category,
    ii.unit,
    ii.supplier,
    COALESCE(ii.unit_cost_cents, 0) AS unit_cost_cents,
    (round(((COALESCE(ii.unit_cost_cents, 0))::numeric / (100)::numeric), 2))::numeric(18,2) AS unit_cost_mxn,
    (COALESCE(ii.unit_cost_cents, 0) > 0) AS tiene_costo,
    COALESCE(r.lineas_expuestas, (0)::bigint) AS lineas_expuestas,
    (round(((COALESCE(r.ventas_expuestas_cents, (0)::bigint))::numeric / (100)::numeric), 2))::numeric(18,2) AS ventas_expuestas_mxn,
    r.ultima_venta,
        CASE
            WHEN (COALESCE(ii.unit_cost_cents, 0) > 0) THEN 'OK'::text
            WHEN (COALESCE(r.ventas_expuestas_cents, (0)::bigint) >= 2000000) THEN 'Crítico — capturar costo ya'::text
            WHEN (COALESCE(r.ventas_expuestas_cents, (0)::bigint) > 0) THEN 'Pendiente — costo faltante'::text
            ELSE 'Sin ventas — baja prioridad'::text
        END AS prioridad
   FROM (public.inventory_items ii
     LEFT JOIN rev r ON (((r.inventory_item_id)::text = (ii.id)::text)))
  WHERE COALESCE(ii.is_active, true)
  ORDER BY (COALESCE(ii.unit_cost_cents, 0) > 0), COALESCE(r.ventas_expuestas_cents, (0)::bigint) DESC;

CREATE OR REPLACE VIEW public.v_bola8_costos_fijos AS
 SELECT fixed_costs.id,
    fixed_costs.concepto,
    COALESCE(fixed_costs.categoria, 'OTROS'::character varying) AS categoria,
    fixed_costs.monto_cents,
    (round(((fixed_costs.monto_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS monto_mensual_mxn,
    (round((((fixed_costs.monto_cents)::numeric / (100)::numeric) / 30.4167), 2))::numeric(18,2) AS monto_diario_mxn,
    (round((((fixed_costs.monto_cents)::numeric / (100)::numeric) * (12)::numeric), 2))::numeric(18,2) AS monto_anual_mxn,
    fixed_costs.is_active,
    fixed_costs.notas,
    fixed_costs.updated_at
   FROM public.fixed_costs
  WHERE COALESCE(fixed_costs.is_active, true)
  ORDER BY fixed_costs.monto_cents DESC;

CREATE OR REPLACE VIEW public.v_bola8_tickets_cerrados AS
 SELECT t.id AS ticket_id,
    t.resource_id,
    r.code AS resource_code,
    r.name AS resource_name,
    r.type AS resource_type,
    t.ticket_type,
    t.status,
    t.opened_at,
    t.closed_at,
    ((t.closed_at AT TIME ZONE 'America/Mexico_City'::text))::date AS fecha_mx,
    (EXTRACT(isodow FROM (t.closed_at AT TIME ZONE 'America/Mexico_City'::text)))::integer AS dia_semana_iso,
    to_char((t.closed_at AT TIME ZONE 'America/Mexico_City'::text), 'Day'::text) AS dia_semana,
    (EXTRACT(hour FROM (t.closed_at AT TIME ZONE 'America/Mexico_City'::text)))::integer AS hora_mx,
    t.payment_type,
    t.payment_type_2,
    COALESCE(t.subtotal_cents, 0) AS subtotal_cents,
    COALESCE(t.discount_cents, 0) AS discount_cents,
    COALESCE(t.pool_time_cents, 0) AS pool_time_cents,
    COALESCE(t.total_cents, 0) AS total_cents,
    COALESCE(t.tip_cents, 0) AS tip_cents,
    COALESCE(t.manual_discount_pct, 0) AS manual_discount_pct,
    COALESCE(t.edited_after_close, false) AS edited_after_close,
    t.customer_name,
    t.rappi_order_id,
    (round(((COALESCE(t.total_cents, 0))::numeric / (100)::numeric), 2))::numeric(18,2) AS total_mxn,
    (round(((COALESCE(t.tip_cents, 0))::numeric / (100)::numeric), 2))::numeric(18,2) AS tip_mxn,
    (round(((COALESCE(t.pool_time_cents, 0))::numeric / (100)::numeric), 2))::numeric(18,2) AS pool_time_mxn,
    (round(((COALESCE(t.discount_cents, 0))::numeric / (100)::numeric), 2))::numeric(18,2) AS descuento_mxn
   FROM (public.tickets t
     LEFT JOIN public.resources r ON (((r.id)::text = (t.resource_id)::text)))
  WHERE (((t.status)::text = 'CLOSED'::text) AND (t.closed_at IS NOT NULL));

CREATE OR REPLACE VIEW public.v_bola8_pagos_desglosados AS
 WITH base AS (
         SELECT v.ticket_id,
            v.closed_at,
            v.fecha_mx,
            v.hora_mx,
            v.dia_semana_iso,
            v.ticket_type,
            v.total_cents,
            v.tip_cents,
            v.payment_type,
            v.payment_type_2,
            COALESCE(t.tendered_cents, 0) AS tendered_1,
            COALESCE(t.tendered_cents_2, 0) AS tendered_2,
            t.tip_source
           FROM (public.v_bola8_tickets_cerrados v
             JOIN public.tickets t ON (((t.id)::text = (v.ticket_id)::text)))
        ), split AS (
         SELECT b.ticket_id,
            b.closed_at,
            b.fecha_mx,
            b.hora_mx,
            b.dia_semana_iso,
            b.ticket_type,
            b.total_cents,
            b.tip_cents,
            b.payment_type,
            b.payment_type_2,
            b.tendered_1,
            b.tendered_2,
            b.tip_source,
            (
                CASE
                    WHEN (b.payment_type_2 IS NULL) THEN (0)::numeric
                    WHEN ((b.tip_source)::text = (b.payment_type_2)::text) THEN (b.tip_cents)::numeric
                    WHEN ((b.tip_source)::text = (b.payment_type)::text) THEN (0)::numeric
                    WHEN ((b.tendered_1 + b.tendered_2) > 0) THEN round((((b.tip_cents)::numeric * (b.tendered_2)::numeric) / ((b.tendered_1 + b.tendered_2))::numeric))
                    ELSE (0)::numeric
                END)::integer AS leg2_tip_cents,
            ((b.payment_type_2 IS NOT NULL) AND (b.tip_cents > 0) AND ((b.tip_source IS NULL) OR (((b.tip_source)::text <> (b.payment_type)::text) AND ((b.tip_source)::text <> (b.payment_type_2)::text)))) AS tip_estimado
           FROM base b
        ), alloc AS (
         SELECT s.ticket_id,
            s.closed_at,
            s.fecha_mx,
            s.hora_mx,
            s.dia_semana_iso,
            s.ticket_type,
            s.total_cents,
            s.tip_cents,
            s.payment_type,
            s.payment_type_2,
            s.tendered_1,
            s.tendered_2,
            s.tip_source,
            s.leg2_tip_cents,
            s.tip_estimado,
            LEAST(GREATEST((s.tendered_2 - s.leg2_tip_cents), 0), s.total_cents) AS leg2_sales_cents
           FROM split s
        ), legs AS (
         SELECT alloc.ticket_id,
            alloc.closed_at,
            alloc.fecha_mx,
            alloc.hora_mx,
            alloc.dia_semana_iso,
            alloc.ticket_type,
            alloc.total_cents,
            alloc.tip_estimado,
            1 AS orden_pago,
            alloc.payment_type AS metodo_pago,
            (alloc.total_cents -
                CASE
                    WHEN (alloc.payment_type_2 IS NULL) THEN 0
                    ELSE alloc.leg2_sales_cents
                END) AS monto_cents,
            (alloc.tip_cents -
                CASE
                    WHEN (alloc.payment_type_2 IS NULL) THEN 0
                    ELSE alloc.leg2_tip_cents
                END) AS propina_cents,
            (alloc.payment_type_2 IS NOT NULL) AS es_split
           FROM alloc
        UNION ALL
         SELECT alloc.ticket_id,
            alloc.closed_at,
            alloc.fecha_mx,
            alloc.hora_mx,
            alloc.dia_semana_iso,
            alloc.ticket_type,
            alloc.total_cents,
            alloc.tip_estimado,
            2,
            alloc.payment_type_2,
            alloc.leg2_sales_cents,
            alloc.leg2_tip_cents,
            true
           FROM alloc
          WHERE ((alloc.payment_type_2 IS NOT NULL) AND ((alloc.leg2_sales_cents > 0) OR (alloc.leg2_tip_cents > 0)))
        )
 SELECT legs.ticket_id,
    legs.closed_at,
    legs.fecha_mx,
    legs.hora_mx,
    legs.dia_semana_iso,
    legs.ticket_type,
    COALESCE(legs.metodo_pago, 'DESCONOCIDO'::character varying) AS metodo_pago,
    legs.orden_pago,
    legs.es_split,
    legs.monto_cents,
    (round(((legs.monto_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS monto_mxn,
    GREATEST(legs.propina_cents, 0) AS propina_cents,
    (round(((GREATEST(legs.propina_cents, 0))::numeric / (100)::numeric), 2))::numeric(18,2) AS propina_mxn,
    legs.tip_estimado AS propina_es_estimada
   FROM legs
  WHERE ((legs.monto_cents > 0) OR (legs.propina_cents > 0));

CREATE OR REPLACE VIEW public.v_bola8_flujo_caja AS
 WITH sess AS (
         SELECT cs.id AS session_id,
            cs.date AS fecha_sesion,
            ((cs.opened_at AT TIME ZONE 'America/Mexico_City'::text))::date AS fecha_mx,
            cs.status,
            cs.opened_at,
            cs.closed_at,
            COALESCE(cs.opening_fund_cents, 0) AS fondo_inicial_cents,
            cs.closing_cash_counted_cents,
            uo.name AS abierta_por,
            uc.name AS cerrada_por
           FROM ((public.cash_sessions cs
             LEFT JOIN public.users uo ON (((uo.id)::text = (cs.opened_by)::text)))
             LEFT JOIN public.users uc ON (((uc.id)::text = (cs.closed_by)::text)))
        ), ventas AS (
         SELECT s.session_id,
            sum(
                CASE
                    WHEN ((p.metodo_pago)::text = 'CASH'::text) THEN p.monto_cents
                    ELSE 0
                END) AS efectivo_ventas_cents,
            sum(
                CASE
                    WHEN ((p.metodo_pago)::text = 'CARD'::text) THEN p.monto_cents
                    ELSE 0
                END) AS tarjeta_ventas_cents,
            sum(
                CASE
                    WHEN ((p.metodo_pago)::text <> ALL ((ARRAY['CASH'::character varying, 'CARD'::character varying])::text[])) THEN p.monto_cents
                    ELSE 0
                END) AS otros_ventas_cents,
            sum(
                CASE
                    WHEN ((p.metodo_pago)::text = 'CASH'::text) THEN p.propina_cents
                    ELSE 0
                END) AS propinas_efectivo_cents,
            sum(
                CASE
                    WHEN ((p.metodo_pago)::text <> 'CASH'::text) THEN p.propina_cents
                    ELSE 0
                END) AS propinas_tarjeta_cents,
            sum(p.propina_cents) AS propinas_totales_cents,
            sum(p.monto_cents) AS ventas_totales_cents,
            count(DISTINCT p.ticket_id) AS tickets
           FROM (sess s
             JOIN public.v_bola8_pagos_desglosados p ON (((p.closed_at >= s.opened_at) AND (p.closed_at < COALESCE(s.closed_at, now())))))
          GROUP BY s.session_id
        ), gastos AS (
         SELECT expenses.session_id,
            sum(COALESCE(expenses.amount_cents, 0)) AS gastos_cents,
            count(*) AS num_gastos
           FROM public.expenses
          GROUP BY expenses.session_id
        ), retiros AS (
         SELECT s.session_id,
            sum(COALESCE(sc.amount_cents, 0)) AS retiros_cents,
            count(*) AS num_retiros
           FROM (sess s
             JOIN public.safe_collections sc ON (((sc.created_at >= s.opened_at) AND (sc.created_at < COALESCE(s.closed_at, now())))))
          GROUP BY s.session_id
        ), calc AS (
         SELECT s.session_id,
            s.fecha_sesion,
            s.fecha_mx,
            s.status,
            s.opened_at,
            s.closed_at,
            s.fondo_inicial_cents,
            s.closing_cash_counted_cents,
            s.abierta_por,
            s.cerrada_por,
            COALESCE(v.efectivo_ventas_cents, (0)::bigint) AS efectivo_ventas_cents,
            COALESCE(v.tarjeta_ventas_cents, (0)::bigint) AS tarjeta_ventas_cents,
            COALESCE(v.otros_ventas_cents, (0)::bigint) AS otros_ventas_cents,
            COALESCE(v.propinas_efectivo_cents, (0)::bigint) AS propinas_efectivo_cents,
            COALESCE(v.propinas_tarjeta_cents, (0)::bigint) AS propinas_tarjeta_cents,
            COALESCE(v.propinas_totales_cents, (0)::bigint) AS propinas_totales_cents,
            COALESCE(v.ventas_totales_cents, (0)::bigint) AS ventas_totales_cents,
            COALESCE(v.tickets, (0)::bigint) AS tickets,
            COALESCE(g.gastos_cents, (0)::bigint) AS gastos_cents,
            COALESCE(g.num_gastos, (0)::bigint) AS num_gastos,
            COALESCE(r.retiros_cents, (0)::bigint) AS retiros_cents,
            COALESCE(r.num_retiros, (0)::bigint) AS num_retiros
           FROM (((sess s
             LEFT JOIN ventas v ON (((v.session_id)::text = (s.session_id)::text)))
             LEFT JOIN gastos g ON (((g.session_id)::text = (s.session_id)::text)))
             LEFT JOIN retiros r ON (((r.session_id)::text = (s.session_id)::text)))
        )
 SELECT calc.session_id,
    calc.fecha_sesion,
    calc.fecha_mx,
    calc.status,
    calc.opened_at,
    calc.closed_at,
    calc.abierta_por,
    calc.cerrada_por,
    calc.tickets,
    calc.num_gastos,
    calc.num_retiros,
    (round(((calc.fondo_inicial_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS fondo_inicial_mxn,
    (round(((calc.efectivo_ventas_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS efectivo_ventas_mxn,
    (round(((calc.tarjeta_ventas_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS tarjeta_ventas_mxn,
    (round(((calc.otros_ventas_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS otros_ventas_mxn,
    (round(((calc.ventas_totales_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS ventas_totales_mxn,
    (round(((calc.propinas_efectivo_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS propinas_efectivo_mxn,
    (round(((calc.propinas_tarjeta_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS propinas_tarjeta_mxn,
    (round(((calc.propinas_totales_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS propinas_pagadas_mxn,
    (round(((calc.gastos_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS gastos_mxn,
    (round(((calc.retiros_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS retiros_caja_fuerte_mxn,
    (round((((((((calc.fondo_inicial_cents + calc.efectivo_ventas_cents) + calc.propinas_efectivo_cents) - calc.propinas_totales_cents) - calc.gastos_cents) - calc.retiros_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS efectivo_esperado_mxn,
    (round(((((((calc.fondo_inicial_cents + calc.efectivo_ventas_cents) + calc.propinas_efectivo_cents) - calc.gastos_cents) - calc.retiros_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS efectivo_esperado_sin_pago_propinas_mxn,
        CASE
            WHEN (calc.closing_cash_counted_cents IS NULL) THEN NULL::numeric
            ELSE (round(((calc.closing_cash_counted_cents)::numeric / (100)::numeric), 2))::numeric(18,2)
        END AS efectivo_contado_mxn,
        CASE
            WHEN (calc.closing_cash_counted_cents IS NULL) THEN NULL::numeric
            ELSE (round((((calc.closing_cash_counted_cents - (((((calc.fondo_inicial_cents + calc.efectivo_ventas_cents) + calc.propinas_efectivo_cents) - calc.propinas_totales_cents) - calc.gastos_cents) - calc.retiros_cents)))::numeric / (100)::numeric), 2))::numeric(18,2)
        END AS diferencia_mxn,
        CASE
            WHEN (calc.closing_cash_counted_cents IS NULL) THEN 'Sesión abierta'::text
            WHEN (abs((calc.closing_cash_counted_cents - (((((calc.fondo_inicial_cents + calc.efectivo_ventas_cents) + calc.propinas_efectivo_cents) - calc.propinas_totales_cents) - calc.gastos_cents) - calc.retiros_cents))) <= GREATEST((5000)::bigint, (((((((calc.fondo_inicial_cents + calc.efectivo_ventas_cents) + calc.propinas_efectivo_cents) - calc.propinas_totales_cents) - calc.gastos_cents) - calc.retiros_cents) * 2) / 100))) THEN 'OK'::text
            WHEN (calc.closing_cash_counted_cents < (((((calc.fondo_inicial_cents + calc.efectivo_ventas_cents) + calc.propinas_efectivo_cents) - calc.propinas_totales_cents) - calc.gastos_cents) - calc.retiros_cents)) THEN
            CASE
                WHEN (((((((calc.fondo_inicial_cents + calc.efectivo_ventas_cents) + calc.propinas_efectivo_cents) - calc.propinas_totales_cents) - calc.gastos_cents) - calc.retiros_cents) - calc.closing_cash_counted_cents) >= GREATEST((50000)::bigint, (((((((calc.fondo_inicial_cents + calc.efectivo_ventas_cents) + calc.propinas_efectivo_cents) - calc.propinas_totales_cents) - calc.gastos_cents) - calc.retiros_cents) * 10) / 100))) THEN 'Faltante grave'::text
                ELSE 'Faltante'::text
            END
            ELSE 'Sobrante'::text
        END AS diagnostico_caja
   FROM calc;

CREATE OR REPLACE VIEW public.v_bola8_forecast_compras AS
 WITH consumo AS (
         SELECT inventory_movements.inventory_item_id,
            (round(sum(
                CASE
                    WHEN ((inventory_movements.event_type)::text = ANY (ARRAY[('SALE_DEDUCTION'::character varying)::text, ('SALE_CONSUMPTION'::character varying)::text])) THEN abs(inventory_movements.quantity_delta)
                    WHEN ((inventory_movements.event_type)::text = 'VOID_REVERSAL'::text) THEN (- abs(inventory_movements.quantity_delta))
                    ELSE (0)::numeric
                END), 2))::numeric(18,2) AS consumo_neto_28d
           FROM public.inventory_movements
          WHERE (inventory_movements.created_at >= (now() - '28 days'::interval))
          GROUP BY inventory_movements.inventory_item_id
        ), calc AS (
         SELECT ii.id AS inventory_item_id,
            ii.name AS insumo,
            ii.category,
            ii.unit,
            (round((ii.stock_quantity)::numeric, 2))::numeric(18,2) AS stock_quantity,
            (round(COALESCE(ii.low_stock_threshold, (0)::numeric), 2))::numeric(18,2) AS low_stock_threshold,
            (round(((COALESCE(ii.unit_cost_cents, 0))::numeric / (100)::numeric), 2))::numeric(18,2) AS unit_cost_mxn,
            (round(((COALESCE(ii.purchase_cost_cents, 0))::numeric / (100)::numeric), 2))::numeric(18,2) AS purchase_cost_mxn,
            (round(COALESCE(ii.purchase_pack_size, (1)::numeric), 2))::numeric(18,2) AS purchase_pack_size,
            ii.supplier,
            (COALESCE(c.consumo_neto_28d, 0.00))::numeric(18,2) AS consumo_neto_28d,
            (round((COALESCE(c.consumo_neto_28d, (0)::numeric) / (4)::numeric), 2))::numeric(18,2) AS consumo_promedio_semanal,
                CASE
                    WHEN (COALESCE(c.consumo_neto_28d, (0)::numeric) > (0)::numeric) THEN (round(((ii.stock_quantity)::numeric / NULLIF((COALESCE(c.consumo_neto_28d, (0)::numeric) / (28)::numeric), (0)::numeric)), 2))::numeric(18,2)
                    ELSE NULL::numeric
                END AS dias_cobertura
           FROM (public.inventory_items ii
             LEFT JOIN consumo c ON (((c.inventory_item_id)::text = (ii.id)::text)))
          WHERE (COALESCE(ii.is_active, true) = true)
        )
 SELECT calc.inventory_item_id,
    calc.insumo,
    calc.category,
    calc.unit,
    calc.stock_quantity,
    calc.low_stock_threshold,
    calc.unit_cost_mxn,
    calc.purchase_cost_mxn,
    calc.purchase_pack_size,
    calc.supplier,
    calc.consumo_neto_28d,
    calc.consumo_promedio_semanal,
    calc.dias_cobertura,
    (GREATEST(ceil(((calc.consumo_promedio_semanal * (2)::numeric) - calc.stock_quantity)), (0)::numeric))::numeric(18,2) AS sugerido_comprar_unidades,
    (round((GREATEST(ceil(((calc.consumo_promedio_semanal * (2)::numeric) - calc.stock_quantity)), (0)::numeric) * calc.unit_cost_mxn), 2))::numeric(18,2) AS costo_estimado_compra_mxn,
        CASE
            WHEN (calc.dias_cobertura IS NULL) THEN 'Sin consumo ├║ltimos 28 d├¡as'::text
            WHEN (calc.dias_cobertura < (7)::numeric) THEN 'Comprar urgente'::text
            WHEN (calc.dias_cobertura < (14)::numeric) THEN 'Comprar esta semana'::text
            WHEN (calc.stock_quantity <= COALESCE(calc.low_stock_threshold, (0)::numeric)) THEN 'Debajo de m├¡nimo'::text
            ELSE 'OK'::text
        END AS recomendacion_compra
   FROM calc
  ORDER BY
        CASE
            WHEN (calc.dias_cobertura IS NULL) THEN 4
            WHEN (calc.dias_cobertura < (7)::numeric) THEN 1
            WHEN (calc.dias_cobertura < (14)::numeric) THEN 2
            ELSE 3
        END, calc.dias_cobertura, calc.insumo;

CREATE OR REPLACE VIEW public.v_bola8_forecast_semanal AS
 WITH daily AS (
         SELECT v_bola8_tickets_cerrados.fecha_mx,
            (EXTRACT(isodow FROM v_bola8_tickets_cerrados.fecha_mx))::integer AS dia_semana_iso,
            (round(((sum(v_bola8_tickets_cerrados.total_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS ventas_mxn,
            count(*) AS tickets
           FROM public.v_bola8_tickets_cerrados
          WHERE (v_bola8_tickets_cerrados.fecha_mx >= (CURRENT_DATE - '56 days'::interval))
          GROUP BY v_bola8_tickets_cerrados.fecha_mx
        ), baseline AS (
         SELECT daily.dia_semana_iso,
            (round(avg(daily.ventas_mxn), 2))::numeric(18,2) AS forecast_ventas_mxn,
            (round(avg(daily.tickets), 2))::numeric(18,2) AS forecast_tickets
           FROM daily
          GROUP BY daily.dia_semana_iso
        ), next_7 AS (
         SELECT (generate_series((CURRENT_DATE)::timestamp without time zone, (CURRENT_DATE + '6 days'::interval), '1 day'::interval))::date AS fecha_forecast
        )
 SELECT n.fecha_forecast,
    (EXTRACT(isodow FROM n.fecha_forecast))::integer AS dia_semana_iso,
    TRIM(BOTH FROM to_char((n.fecha_forecast)::timestamp with time zone, 'Day'::text)) AS dia_semana,
    (COALESCE(b.forecast_ventas_mxn, 0.00))::numeric(18,2) AS forecast_ventas_mxn,
    (COALESCE(b.forecast_tickets, 0.00))::numeric(18,2) AS forecast_tickets
   FROM (next_7 n
     LEFT JOIN baseline b ON ((b.dia_semana_iso = (EXTRACT(isodow FROM n.fecha_forecast))::integer)))
  ORDER BY n.fecha_forecast;

CREATE OR REPLACE VIEW public.v_bola8_kpis_diarios AS
 SELECT v_bola8_tickets_cerrados.fecha_mx,
    count(*) AS tickets_cerrados,
    (round(((sum(v_bola8_tickets_cerrados.total_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS ventas_mxn,
    (round(((sum(v_bola8_tickets_cerrados.pool_time_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS billar_mxn,
    (round(((sum(v_bola8_tickets_cerrados.discount_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS descuentos_mxn,
    (round(((sum(v_bola8_tickets_cerrados.tip_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS propinas_mxn,
    (round((avg(v_bola8_tickets_cerrados.total_cents) / (100)::numeric), 2))::numeric(18,2) AS ticket_promedio_mxn,
    (round(((sum(
        CASE
            WHEN (((v_bola8_tickets_cerrados.payment_type)::text = 'CASH'::text) OR ((v_bola8_tickets_cerrados.payment_type_2)::text = 'CASH'::text)) THEN v_bola8_tickets_cerrados.total_cents
            ELSE 0
        END))::numeric / (100)::numeric), 2))::numeric(18,2) AS ventas_con_efectivo_mxn,
    (round(((sum(
        CASE
            WHEN (((v_bola8_tickets_cerrados.payment_type)::text = 'CARD'::text) OR ((v_bola8_tickets_cerrados.payment_type_2)::text = 'CARD'::text)) THEN v_bola8_tickets_cerrados.total_cents
            ELSE 0
        END))::numeric / (100)::numeric), 2))::numeric(18,2) AS ventas_con_tarjeta_mxn,
    sum(
        CASE
            WHEN (v_bola8_tickets_cerrados.manual_discount_pct > 0) THEN 1
            ELSE 0
        END) AS tickets_con_descuento_manual,
    sum(
        CASE
            WHEN v_bola8_tickets_cerrados.edited_after_close THEN 1
            ELSE 0
        END) AS tickets_editados_despues_cierre
   FROM public.v_bola8_tickets_cerrados
  GROUP BY v_bola8_tickets_cerrados.fecha_mx
  ORDER BY v_bola8_tickets_cerrados.fecha_mx;

CREATE OR REPLACE VIEW public.v_bola8_kpis_ejecutivos AS
 SELECT min(v_bola8_tickets_cerrados.fecha_mx) AS fecha_inicio,
    max(v_bola8_tickets_cerrados.fecha_mx) AS fecha_fin,
    count(*) AS tickets_cerrados,
    (round(((sum(v_bola8_tickets_cerrados.total_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS ventas_mxn,
    (round(((sum(v_bola8_tickets_cerrados.pool_time_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS billar_mxn,
    (round(((sum(v_bola8_tickets_cerrados.discount_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS descuentos_mxn,
    (round(((sum(v_bola8_tickets_cerrados.tip_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS propinas_mxn,
    (round((avg(v_bola8_tickets_cerrados.total_cents) / (100)::numeric), 2))::numeric(18,2) AS ticket_promedio_mxn,
    (round((((sum(v_bola8_tickets_cerrados.total_cents))::numeric / (NULLIF(count(DISTINCT v_bola8_tickets_cerrados.fecha_mx), 0))::numeric) / (100)::numeric), 2))::numeric(18,2) AS venta_promedio_diaria_mxn
   FROM public.v_bola8_tickets_cerrados;

CREATE OR REPLACE VIEW public.v_bola8_personal_desempeno AS
 WITH lineas AS (
         SELECT v_bola8_lineas_venta.ticket_id,
            sum(v_bola8_lineas_venta.quantity) AS unidades,
            sum(v_bola8_lineas_venta.net_sales_cents) AS net_cents,
            sum(v_bola8_lineas_venta.total_cost_cents) AS costo_cents,
            sum(v_bola8_lineas_venta.gross_profit_cents) AS utilidad_cents,
            sum(
                CASE
                    WHEN (v_bola8_lineas_venta.total_cost_cents > 0) THEN v_bola8_lineas_venta.net_sales_cents
                    ELSE 0
                END) AS net_con_costo_cents,
            count(*) AS lineas
           FROM public.v_bola8_lineas_venta
          GROUP BY v_bola8_lineas_venta.ticket_id
        )
 SELECT v.ticket_id,
    v.fecha_mx,
    v.hora_mx,
    v.dia_semana_iso,
    v.ticket_type,
    v.resource_name,
    v.resource_type,
    t.opened_by,
    uo.name AS abrio,
    uo.role AS rol_abrio,
    t.closed_by,
    uc.name AS cerro,
    uc.role AS rol_cerro,
    COALESCE(ur.name, NULL::character varying) AS reabrio,
    COALESCE(t.was_reopened, false) AS fue_reabierto,
    v.edited_after_close,
    v.manual_discount_pct,
    COALESCE(l.lineas, (0)::bigint) AS lineas,
    COALESCE(l.unidades, (0)::bigint) AS unidades,
    (round(((v.total_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS total_mxn,
    (round(((v.pool_time_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS billar_mxn,
    (round(((v.tip_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS propina_mxn,
    (round(((v.discount_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS descuento_mxn,
    (round(((COALESCE(l.net_cents, (0)::bigint))::numeric / (100)::numeric), 2))::numeric(18,2) AS venta_articulos_mxn,
    (round(((COALESCE(l.costo_cents, (0)::bigint))::numeric / (100)::numeric), 2))::numeric(18,2) AS costo_mxn,
    (round(((COALESCE(l.utilidad_cents, (0)::bigint))::numeric / (100)::numeric), 2))::numeric(18,2) AS utilidad_mxn,
        CASE
            WHEN (COALESCE(l.net_cents, (0)::bigint) > 0) THEN (round(((100.0 * (COALESCE(l.net_con_costo_cents, (0)::bigint))::numeric) / (NULLIF(l.net_cents, 0))::numeric), 2))::numeric(18,2)
            ELSE NULL::numeric
        END AS cobertura_costo_pct,
        CASE
            WHEN ((v.tip_cents > 0) AND (v.total_cents > 0)) THEN (round(((100.0 * (v.tip_cents)::numeric) / (NULLIF(v.total_cents, 0))::numeric), 2))::numeric(18,2)
            ELSE 0.00::numeric(18,2)
        END AS propina_pct,
    (round((EXTRACT(epoch FROM (v.closed_at - v.opened_at)) / (60)::numeric), 2))::numeric(18,2) AS duracion_min
   FROM (((((public.v_bola8_tickets_cerrados v
     JOIN public.tickets t ON (((t.id)::text = (v.ticket_id)::text)))
     LEFT JOIN public.users uo ON (((uo.id)::text = (t.opened_by)::text)))
     LEFT JOIN public.users uc ON (((uc.id)::text = (t.closed_by)::text)))
     LEFT JOIN public.users ur ON (((ur.id)::text = (t.reopened_by)::text)))
     LEFT JOIN lineas l ON (((l.ticket_id)::text = (v.ticket_id)::text)));

CREATE OR REPLACE VIEW public.v_bola8_productos_lentos AS
 WITH ventas_30 AS (
         SELECT v_bola8_lineas_venta.menu_item_id,
            sum(v_bola8_lineas_venta.quantity) AS unidades_30d,
            (round(((sum(v_bola8_lineas_venta.net_sales_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS ventas_30d_mxn,
            max(v_bola8_lineas_venta.fecha_mx) AS ultima_fecha_venta
           FROM public.v_bola8_lineas_venta
          WHERE (v_bola8_lineas_venta.fecha_mx >= (CURRENT_DATE - '30 days'::interval))
          GROUP BY v_bola8_lineas_venta.menu_item_id
        )
 SELECT mi.id AS menu_item_id,
    mi.name AS producto,
    mc.name AS categoria,
    (round(((mi.price_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS precio_mxn,
    COALESCE(v.unidades_30d, (0)::bigint) AS unidades_30d,
    (COALESCE(v.ventas_30d_mxn, 0.00))::numeric(18,2) AS ventas_30d_mxn,
    v.ultima_fecha_venta,
        CASE
            WHEN (COALESCE(v.unidades_30d, (0)::bigint) = 0) THEN 'Sin venta ├║ltimos 30 d├¡as'::text
            WHEN (COALESCE(v.unidades_30d, (0)::bigint) <= 3) THEN 'Baja rotaci├│n'::text
            ELSE 'OK'::text
        END AS diagnostico
   FROM ((public.menu_items mi
     LEFT JOIN public.menu_categories mc ON (((mc.id)::text = (mi.category_id)::text)))
     LEFT JOIN ventas_30 v ON (((v.menu_item_id)::text = (mi.id)::text)))
  WHERE ((COALESCE(mi.is_active, true) = true) AND (COALESCE(v.unidades_30d, (0)::bigint) <= 3))
  ORDER BY COALESCE(v.unidades_30d, (0)::bigint), mi.name;

CREATE OR REPLACE VIEW public.v_bola8_promo_redenciones AS
 SELECT lip.id AS redencion_id,
    lip.ticket_id,
    lip.line_item_id,
    lip.promotion_id,
    p.name AS promocion,
    p.promo_type,
    p.discount_type,
    lip.applied_at,
    ((lip.applied_at AT TIME ZONE 'America/Mexico_City'::text))::date AS fecha_mx,
    (EXTRACT(hour FROM (lip.applied_at AT TIME ZONE 'America/Mexico_City'::text)))::integer AS hora_mx,
    l.producto,
    l.categoria,
    l.quantity,
    lip.discount_cents,
    (round(((lip.discount_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS descuento_mxn,
    (round(((COALESCE(l.net_sales_cents, 0))::numeric / (100)::numeric), 2))::numeric(18,2) AS venta_linea_mxn,
    (round(((COALESCE(l.gross_profit_cents, 0))::numeric / (100)::numeric), 2))::numeric(18,2) AS utilidad_linea_mxn,
    (round((((COALESCE(l.gross_profit_cents, 0) - lip.discount_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS utilidad_neta_promo_mxn,
    d.decision,
    d.decided_at,
    ud.name AS decidio_por
   FROM ((((public.line_item_promotions lip
     LEFT JOIN public.promotions p ON (((p.id)::text = (lip.promotion_id)::text)))
     LEFT JOIN public.v_bola8_lineas_venta l ON (((l.line_item_id)::text = (lip.line_item_id)::text)))
     LEFT JOIN public.ticket_promo_decisions d ON ((((d.ticket_id)::text = (lip.ticket_id)::text) AND ((d.promotion_id)::text = (lip.promotion_id)::text))))
     LEFT JOIN public.users ud ON (((ud.id)::text = (d.decided_by)::text)));

CREATE OR REPLACE VIEW public.v_bola8_promociones_activas AS
 SELECT p.id AS promotion_id,
    p.name,
    p.promo_type,
    p.discount_type,
    p.discount_value,
    mi.name AS aplica_producto,
    mc.name AS aplica_categoria,
    p.happy_hour_start,
    p.happy_hour_end,
    p.valid_from,
    p.valid_to,
    p.required_quantity,
    p.free_quantity,
    p.discounted_quantity,
    p.max_applications_per_ticket,
    p.is_stackable,
    p.combine_across_items,
    p.priority,
    p.requires_confirmation
   FROM ((public.promotions p
     LEFT JOIN public.menu_items mi ON (((mi.id)::text = (p.applies_to_item_id)::text)))
     LEFT JOIN public.menu_categories mc ON (((mc.id)::text = (p.applies_to_category_id)::text)))
  WHERE ((COALESCE(p.is_active, false) = true) AND (CURRENT_DATE >= p.valid_from) AND (CURRENT_DATE <= p.valid_to))
  ORDER BY p.priority DESC, p.name;

CREATE OR REPLACE VIEW public.v_bola8_utilidad_producto AS
 SELECT v_bola8_lineas_venta.producto,
    v_bola8_lineas_venta.categoria,
    count(DISTINCT v_bola8_lineas_venta.ticket_id) AS tickets,
    sum(v_bola8_lineas_venta.quantity) AS unidades,
    (round(((sum(v_bola8_lineas_venta.net_sales_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS ventas_mxn,
    (round(((sum(v_bola8_lineas_venta.total_cost_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS costo_mxn,
    (round(((sum(v_bola8_lineas_venta.gross_profit_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS utilidad_mxn,
    (round(((100.0 * (sum(v_bola8_lineas_venta.gross_profit_cents))::numeric) / (NULLIF(sum(v_bola8_lineas_venta.net_sales_cents), 0))::numeric), 2))::numeric(18,2) AS margen_pct,
    (round((((sum(v_bola8_lineas_venta.net_sales_cents))::numeric / (NULLIF(sum(v_bola8_lineas_venta.quantity), 0))::numeric) / (100)::numeric), 2))::numeric(18,2) AS precio_promedio_mxn
   FROM public.v_bola8_lineas_venta
  GROUP BY v_bola8_lineas_venta.producto, v_bola8_lineas_venta.categoria
  ORDER BY ((round(((sum(v_bola8_lineas_venta.gross_profit_cents))::numeric / (100)::numeric), 2))::numeric(18,2)) DESC;

CREATE OR REPLACE VIEW public.v_bola8_ventas_por_hora AS
 SELECT v_bola8_tickets_cerrados.hora_mx,
    count(*) AS tickets,
    (round(((sum(v_bola8_tickets_cerrados.total_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS ventas_mxn,
    (round((avg(v_bola8_tickets_cerrados.total_cents) / (100)::numeric), 2))::numeric(18,2) AS ticket_promedio_mxn
   FROM public.v_bola8_tickets_cerrados
  GROUP BY v_bola8_tickets_cerrados.hora_mx
  ORDER BY v_bola8_tickets_cerrados.hora_mx;

CREATE OR REPLACE VIEW public.v_bola8_recomendaciones AS
 WITH top_margin AS (
         SELECT v_bola8_utilidad_producto.producto,
            v_bola8_utilidad_producto.categoria,
            v_bola8_utilidad_producto.ventas_mxn,
            v_bola8_utilidad_producto.utilidad_mxn,
            v_bola8_utilidad_producto.margen_pct
           FROM public.v_bola8_utilidad_producto
          WHERE ((v_bola8_utilidad_producto.ventas_mxn > (0)::numeric) AND (v_bola8_utilidad_producto.margen_pct IS NOT NULL))
          ORDER BY v_bola8_utilidad_producto.margen_pct DESC, v_bola8_utilidad_producto.utilidad_mxn DESC
         LIMIT 10
        ), peak_hours AS (
         SELECT v_bola8_ventas_por_hora.hora_mx,
            v_bola8_ventas_por_hora.ventas_mxn
           FROM public.v_bola8_ventas_por_hora
          ORDER BY v_bola8_ventas_por_hora.ventas_mxn DESC
         LIMIT 3
        ), slow AS (
         SELECT v_bola8_productos_lentos.producto,
            v_bola8_productos_lentos.categoria,
            v_bola8_productos_lentos.unidades_30d
           FROM public.v_bola8_productos_lentos
         LIMIT 10
        ), urgent_buy AS (
         SELECT v_bola8_forecast_compras.insumo,
            v_bola8_forecast_compras.dias_cobertura,
            v_bola8_forecast_compras.sugerido_comprar_unidades
           FROM public.v_bola8_forecast_compras
          WHERE (v_bola8_forecast_compras.recomendacion_compra = ANY (ARRAY['Comprar urgente'::text, 'Comprar esta semana'::text, 'Debajo de m├¡nimo'::text]))
         LIMIT 10
        )
 SELECT 'Ventas'::text AS area,
    'Impulsar productos de alto margen'::text AS recomendacion,
    ('Prioriza combos y upsell con: '::text || COALESCE(string_agg((top_margin.producto)::text, ', '::text), 'Sin datos suficientes'::text)) AS detalle
   FROM top_margin
UNION ALL
 SELECT 'Operaci├│n'::text AS area,
    'Alinear personal y cocina a horas pico'::text AS recomendacion,
    ('Horas con mayor venta hist├│rica: '::text || COALESCE(string_agg(((peak_hours.hora_mx)::text || ':00'::text), ', '::text), 'Sin datos suficientes'::text)) AS detalle
   FROM peak_hours
UNION ALL
 SELECT 'Men├║'::text AS area,
    'Revisar o promocionar productos lentos'::text AS recomendacion,
    ('Productos con baja rotaci├│n: '::text || COALESCE(string_agg((slow.producto)::text, ', '::text), 'Sin datos suficientes'::text)) AS detalle
   FROM slow
UNION ALL
 SELECT 'Compras'::text AS area,
    'Prevenir quiebres de inventario'::text AS recomendacion,
    ('Insumos a comprar: '::text || COALESCE(string_agg(((((urgent_buy.insumo)::text || ' ('::text) || (urgent_buy.sugerido_comprar_unidades)::text) || ')'::text), ', '::text), 'Sin compras urgentes'::text)) AS detalle
   FROM urgent_buy;

CREATE OR REPLACE VIEW public.v_bola8_rentabilidad_diaria AS
 WITH fijo AS (
         SELECT (COALESCE(sum(fixed_costs.monto_cents), (0)::bigint))::numeric AS mensual_cents
           FROM public.fixed_costs
          WHERE COALESCE(fixed_costs.is_active, true)
        ), tick AS (
         SELECT v_bola8_tickets_cerrados.fecha_mx,
            count(*) AS tickets,
            sum(v_bola8_tickets_cerrados.total_cents) AS ventas_cents,
            sum(v_bola8_tickets_cerrados.pool_time_cents) AS billar_cents,
            sum(v_bola8_tickets_cerrados.tip_cents) AS propinas_cents,
            sum(v_bola8_tickets_cerrados.discount_cents) AS descuentos_cents
           FROM public.v_bola8_tickets_cerrados
          GROUP BY v_bola8_tickets_cerrados.fecha_mx
        ), lin AS (
         SELECT v_bola8_lineas_venta.fecha_mx,
            sum(v_bola8_lineas_venta.net_sales_cents) AS articulos_cents,
            sum(v_bola8_lineas_venta.total_cost_cents) AS cogs_cents,
            sum(v_bola8_lineas_venta.gross_profit_cents) AS utilidad_art_cents,
            sum(
                CASE
                    WHEN (v_bola8_lineas_venta.total_cost_cents > 0) THEN v_bola8_lineas_venta.net_sales_cents
                    ELSE 0
                END) AS art_con_costo_cents
           FROM public.v_bola8_lineas_venta
          GROUP BY v_bola8_lineas_venta.fecha_mx
        )
 SELECT t.fecha_mx,
    t.tickets,
    (round(((t.ventas_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS ventas_mxn,
    (round(((t.billar_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS billar_mxn,
    (round(((t.propinas_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS propinas_mxn,
    (round(((t.descuentos_cents)::numeric / (100)::numeric), 2))::numeric(18,2) AS descuentos_mxn,
    (round(((COALESCE(l.articulos_cents, (0)::bigint))::numeric / (100)::numeric), 2))::numeric(18,2) AS articulos_mxn,
    (round(((COALESCE(l.cogs_cents, (0)::bigint))::numeric / (100)::numeric), 2))::numeric(18,2) AS cogs_mxn,
    (round(((COALESCE(l.utilidad_art_cents, (0)::bigint))::numeric / (100)::numeric), 2))::numeric(18,2) AS utilidad_articulos_mxn,
    (round((((COALESCE(l.utilidad_art_cents, (0)::bigint) + t.billar_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS utilidad_bruta_mxn,
    (round(((f.mensual_cents / (100)::numeric) / 30.4167), 2))::numeric(18,2) AS costo_fijo_diario_mxn,
    (round(((((COALESCE(l.utilidad_art_cents, (0)::bigint) + t.billar_cents))::numeric - (f.mensual_cents / 30.4167)) / (100)::numeric), 2))::numeric(18,2) AS utilidad_neta_mxn,
        CASE
            WHEN ((COALESCE(l.utilidad_art_cents, (0)::bigint) + t.billar_cents) > 0) THEN (round(((((f.mensual_cents / 30.4167) / ((COALESCE(l.utilidad_art_cents, (0)::bigint) + t.billar_cents))::numeric) * (t.ventas_cents)::numeric) / (100)::numeric), 2))::numeric(18,2)
            ELSE NULL::numeric
        END AS punto_equilibrio_ventas_mxn,
        CASE
            WHEN (COALESCE(l.articulos_cents, (0)::bigint) > 0) THEN (round(((100.0 * (COALESCE(l.art_con_costo_cents, (0)::bigint))::numeric) / (NULLIF(l.articulos_cents, 0))::numeric), 2))::numeric(18,2)
            ELSE NULL::numeric
        END AS cobertura_costo_pct
   FROM ((tick t
     LEFT JOIN lin l ON ((l.fecha_mx = t.fecha_mx)))
     CROSS JOIN fijo f);

CREATE OR REPLACE VIEW public.v_bola8_top_productos AS
 SELECT v_bola8_lineas_venta.producto,
    v_bola8_lineas_venta.categoria,
    sum(v_bola8_lineas_venta.quantity) AS unidades,
    count(DISTINCT v_bola8_lineas_venta.ticket_id) AS tickets,
    (round(((sum(v_bola8_lineas_venta.net_sales_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS ventas_mxn,
    (round(((sum(v_bola8_lineas_venta.gross_profit_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS utilidad_mxn,
    (round(((100.0 * (sum(v_bola8_lineas_venta.gross_profit_cents))::numeric) / (NULLIF(sum(v_bola8_lineas_venta.net_sales_cents), 0))::numeric), 2))::numeric(18,2) AS margen_pct
   FROM public.v_bola8_lineas_venta
  GROUP BY v_bola8_lineas_venta.producto, v_bola8_lineas_venta.categoria
  ORDER BY ((round(((sum(v_bola8_lineas_venta.net_sales_cents))::numeric / (100)::numeric), 2))::numeric(18,2)) DESC;

CREATE OR REPLACE VIEW public.v_bola8_varianza_inventario AS
 WITH mov AS (
         SELECT m.inventory_item_id,
            sum(
                CASE
                    WHEN ((m.event_type)::text = ANY ((ARRAY['SALE_DEDUCTION'::character varying, 'SALE_CONSUMPTION'::character varying])::text[])) THEN abs(m.quantity_delta)
                    ELSE (0)::numeric
                END) AS consumo_ventas,
            sum(
                CASE
                    WHEN ((m.event_type)::text = 'VOID_REVERSAL'::text) THEN abs(m.quantity_delta)
                    ELSE (0)::numeric
                END) AS reversas_void,
            sum(
                CASE
                    WHEN ((m.event_type)::text = 'WASTE'::text) THEN abs(m.quantity_delta)
                    ELSE (0)::numeric
                END) AS merma_declarada,
            sum(
                CASE
                    WHEN ((m.event_type)::text = 'MANUAL_ADJUSTMENT'::text) THEN m.quantity_delta
                    ELSE (0)::numeric
                END) AS ajuste_manual,
            sum(
                CASE
                    WHEN ((m.event_type)::text = 'COUNT_ADJUSTMENT'::text) THEN m.quantity_delta
                    ELSE (0)::numeric
                END) AS ajuste_conteo,
            sum(
                CASE
                    WHEN ((m.event_type)::text = 'RESTOCK'::text) THEN abs(m.quantity_delta)
                    ELSE (0)::numeric
                END) AS reabastecimiento,
            count(*) FILTER (WHERE ((m.event_type)::text = ANY ((ARRAY['MANUAL_ADJUSTMENT'::character varying, 'COUNT_ADJUSTMENT'::character varying, 'WASTE'::character varying])::text[]))) AS eventos_no_venta
           FROM public.inventory_movements m
          WHERE (m.created_at >= (now() - '28 days'::interval))
          GROUP BY m.inventory_item_id
        ), calc AS (
         SELECT ii.id,
            ii.name,
            ii.category,
            ii.unit,
            COALESCE(ii.unit_cost_cents, 0) AS unit_cost_cents,
            COALESCE(m.consumo_ventas, (0)::numeric) AS consumo_ventas,
            COALESCE(m.reversas_void, (0)::numeric) AS reversas_void,
            COALESCE(m.merma_declarada, (0)::numeric) AS merma_declarada,
            COALESCE(m.ajuste_manual, (0)::numeric) AS ajuste_manual,
            COALESCE(m.ajuste_conteo, (0)::numeric) AS ajuste_conteo,
            COALESCE(m.reabastecimiento, (0)::numeric) AS reabastecimiento,
            COALESCE(m.eventos_no_venta, (0)::bigint) AS eventos_no_venta,
            (COALESCE(m.merma_declarada, (0)::numeric) + GREATEST((- (COALESCE(m.ajuste_manual, (0)::numeric) + COALESCE(m.ajuste_conteo, (0)::numeric))), (0)::numeric)) AS merma_total_unidades
           FROM (public.inventory_items ii
             LEFT JOIN mov m ON (((m.inventory_item_id)::text = (ii.id)::text)))
          WHERE COALESCE(ii.is_active, true)
        )
 SELECT calc.id AS inventory_item_id,
    calc.name AS insumo,
    calc.category,
    calc.unit,
    (round((calc.consumo_ventas - calc.reversas_void), 2))::numeric(18,2) AS consumo_neto_28d,
    (round(calc.merma_declarada, 2))::numeric(18,2) AS merma_declarada_28d,
    (round(calc.ajuste_manual, 2))::numeric(18,2) AS ajuste_manual_28d,
    (round(calc.ajuste_conteo, 2))::numeric(18,2) AS ajuste_conteo_28d,
    (round(calc.reabastecimiento, 2))::numeric(18,2) AS reabastecimiento_28d,
    calc.eventos_no_venta,
    (round(calc.merma_total_unidades, 2))::numeric(18,2) AS merma_total_unidades,
    (round(((calc.merma_total_unidades * (calc.unit_cost_cents)::numeric) / (100)::numeric), 2))::numeric(18,2) AS merma_valorizada_mxn,
        CASE
            WHEN ((calc.consumo_ventas - calc.reversas_void) > (0)::numeric) THEN (round(((100.0 * calc.merma_total_unidades) / NULLIF((calc.consumo_ventas - calc.reversas_void), (0)::numeric)), 2))::numeric(18,2)
            ELSE NULL::numeric
        END AS merma_pct_sobre_consumo,
        CASE
            WHEN ((calc.unit_cost_cents = 0) AND (calc.merma_total_unidades > (0)::numeric)) THEN 'Merma sin valorizar — falta costo unitario'::text
            WHEN (calc.merma_total_unidades = (0)::numeric) THEN 'Sin merma'::text
            WHEN (((calc.consumo_ventas - calc.reversas_void) > (0)::numeric) AND ((calc.merma_total_unidades / NULLIF((calc.consumo_ventas - calc.reversas_void), (0)::numeric)) > 0.10)) THEN 'Merma alta — investigar'::text
            WHEN (calc.merma_total_unidades > (0)::numeric) THEN 'Merma normal'::text
            ELSE 'Sin datos'::text
        END AS diagnostico_merma
   FROM calc
  ORDER BY ((calc.merma_total_unidades * (calc.unit_cost_cents)::numeric) / (100)::numeric) DESC, ((round(calc.merma_total_unidades, 2))::numeric(18,2)) DESC;

CREATE OR REPLACE VIEW public.v_bola8_ventas_por_dia_semana AS
 SELECT v_bola8_tickets_cerrados.dia_semana_iso,
    TRIM(BOTH FROM to_char((v_bola8_tickets_cerrados.fecha_mx)::timestamp with time zone, 'Day'::text)) AS dia_semana,
    count(*) AS tickets,
    (round(((sum(v_bola8_tickets_cerrados.total_cents))::numeric / (100)::numeric), 2))::numeric(18,2) AS ventas_mxn,
    (round((avg(v_bola8_tickets_cerrados.total_cents) / (100)::numeric), 2))::numeric(18,2) AS ticket_promedio_mxn
   FROM public.v_bola8_tickets_cerrados
  GROUP BY v_bola8_tickets_cerrados.dia_semana_iso, (TRIM(BOTH FROM to_char((v_bola8_tickets_cerrados.fecha_mx)::timestamp with time zone, 'Day'::text)))
  ORDER BY v_bola8_tickets_cerrados.dia_semana_iso;

CREATE OR REPLACE VIEW public.v_cigarette_box_history AS
 SELECT o.id,
    i.name AS box_item,
    o.brand,
    o.cigs_per_box,
    o.cigs_sold,
    (o.cigs_sold > o.cigs_per_box) AS oversold,
    (o.cigs_sold - o.cigs_per_box) AS oversold_by,
    o.opened_at,
    o.finished_at,
    u.name AS opened_by_name
   FROM ((public.open_cigarette_boxes o
     JOIN public.inventory_items i ON (((i.id)::text = (o.box_item_id)::text)))
     LEFT JOIN public.users u ON (((u.id)::text = (o.opened_by)::text)));

CREATE OR REPLACE VIEW public.v_cigarette_count_sheet AS
 SELECT i.id,
    i.name,
    i.item_type,
    i.stock_quantity AS system_says,
        CASE i.item_type
            WHEN 'CIG_BOX'::text THEN 'contar cajetillas SELLADAS'::text
            ELSE 'contar cigarros SUELTOS'::text
        END AS count_unit,
    c.ratio AS cigs_per_pack
   FROM (public.inventory_items i
     LEFT JOIN public.inventory_conversions c ON ((((c.from_item_id)::text = (i.id)::text) AND ((c.conversion_type)::text = 'PACK_TO_LOOSE'::text))))
  WHERE (((i.item_type)::text = ANY (ARRAY[('CIG_BOX'::character varying)::text, ('CIG_SINGLE'::character varying)::text])) AND i.is_active)
  ORDER BY i.item_type, i.name;

CREATE OR REPLACE VIEW public.v_cigarette_reconciliation AS
 SELECT b.name AS pack_item,
    b.stock_quantity AS packs,
    s.name AS loose_item,
    s.stock_quantity AS loose,
    c.ratio AS per_pack,
    ((b.stock_quantity * c.ratio) + s.stock_quantity) AS total_cigarettes_equiv,
    ( SELECT (max(m.created_at))::date AS max
           FROM public.inventory_movements m
          WHERE (((m.inventory_item_id)::text = (b.id)::text) AND ((m.event_type)::text = ANY (ARRAY[('CONVERSION_OUT'::character varying)::text, ('BOX_OPENING'::character varying)::text])))) AS last_pack_opened
   FROM ((public.inventory_conversions c
     JOIN public.inventory_items b ON (((b.id)::text = (c.from_item_id)::text)))
     JOIN public.inventory_items s ON (((s.id)::text = (c.to_item_id)::text)))
  WHERE ((c.conversion_type)::text = 'PACK_TO_LOOSE'::text);

CREATE OR REPLACE VIEW public.v_convertible_stock AS
 SELECT f.id AS source_id,
    f.name AS source_name,
    f.stock_quantity AS source_stock,
    t.id AS derived_id,
    t.name AS derived_name,
    t.stock_quantity AS derived_stock,
    c.ratio,
    c.conversion_type,
    c.is_automatic,
    (t.stock_quantity + ((f.stock_quantity * c.ratio) * ((1)::numeric - c.loss_factor))) AS max_derived_available
   FROM ((public.inventory_conversions c
     JOIN public.inventory_items f ON (((f.id)::text = (c.from_item_id)::text)))
     JOIN public.inventory_items t ON (((t.id)::text = (c.to_item_id)::text)))
  WHERE (c.is_active AND f.is_active AND t.is_active);

CREATE OR REPLACE VIEW public.v_effective_modifier_rules AS
 SELECT mg.menu_item_id,
    g.id AS group_id,
    g.name AS group_name,
    COALESCE(mg.min_selections, g.min_selections) AS min_selections,
    COALESCE(mg.max_selections, g.max_selections) AS max_selections,
    COALESCE(mg.allow_multiple, g.allow_multiple) AS allow_multiple,
    mg.sort_order
   FROM (public.menu_item_modifier_groups mg
     JOIN public.modifier_groups g ON (((g.id)::text = (mg.modifier_group_id)::text)));

CREATE OR REPLACE VIEW public.v_items_pending_count AS
 SELECT i.id,
    i.name,
    i.unit,
    i.stock_quantity,
    i.category,
        CASE
            WHEN (i.stock_quantity = (0)::numeric) THEN 'EN CERO - bloqueara ventas'::text
            WHEN (i.stock_quantity <= (2)::numeric) THEN 'muy bajo'::text
            ELSE 'revisar'::text
        END AS motivo,
    (EXISTS ( SELECT 1
           FROM public.modifier_inventory_rules r
          WHERE ((r.inventory_item_id)::text = (i.id)::text))) AS usado_por_modificador,
    (EXISTS ( SELECT 1
           FROM public.insumos_base b
          WHERE ((b.inventory_item_id)::text = (i.id)::text))) AS usado_por_receta
   FROM public.inventory_items i
  WHERE (i.is_active AND ((i.stock_quantity <= (2)::numeric) OR ((i.item_type)::text = ANY (ARRAY[('CIG_BOX'::character varying)::text, ('CIG_SINGLE'::character varying)::text]))))
  ORDER BY i.stock_quantity, i.name;

CREATE OR REPLACE VIEW public.v_kds_undelivered AS
 SELECT e.sequence,
    e.event_type,
    e.destination,
    e.ticket_id,
    e.line_item_id,
    e.created_at,
    e.attempt_count,
    (EXTRACT(epoch FROM (clock_timestamp() - e.created_at)))::integer AS age_seconds,
    li.item_name,
    li.quantity,
    li.kds_sent_quantity
   FROM (public.kds_events e
     LEFT JOIN public.ticket_line_items li ON (((li.id)::text = (e.line_item_id)::text)))
  WHERE ((e.acked_at IS NULL) AND (e.created_at > (clock_timestamp() - '24:00:00'::interval)))
  ORDER BY e.sequence;

CREATE OR REPLACE VIEW public.v_kds_watermark_drift AS
 SELECT li.id AS line_item_id,
    li.ticket_id,
    li.item_name,
    li.routing_dest,
    li.quantity,
    li.kds_sent_quantity,
    (li.quantity - li.kds_sent_quantity) AS pending_delta,
    li.status
   FROM (public.ticket_line_items li
     JOIN public.tickets t ON (((t.id)::text = (li.ticket_id)::text)))
  WHERE (((t.status)::text = 'OPEN'::text) AND ((li.status)::text <> 'VOIDED'::text) AND (li.quantity <> li.kds_sent_quantity));

CREATE OR REPLACE VIEW public.v_ledger_reconciliation AS
 WITH latest AS (
         SELECT DISTINCT ON (m.inventory_item_id) m.inventory_item_id,
            m.quantity_after,
            m.created_at
           FROM public.inventory_movements m
          WHERE ((m.quantity_after IS NOT NULL) AND (m.created_at IS NOT NULL) AND (m.created_at >= public.ledger_cutover()))
          ORDER BY m.inventory_item_id, m.seq DESC
        ), counts AS (
         SELECT inventory_movements.inventory_item_id,
            count(*) FILTER (WHERE (inventory_movements.created_at >= public.ledger_cutover())) AS post_moves,
            count(*) FILTER (WHERE (inventory_movements.created_at < public.ledger_cutover())) AS pre_moves,
            count(*) FILTER (WHERE (inventory_movements.created_at IS NULL)) AS undated_moves
           FROM public.inventory_movements
          GROUP BY inventory_movements.inventory_item_id
        )
 SELECT i.id AS inventory_item_id,
    i.name,
    i.item_type,
    i.stock_quantity,
    l.quantity_after AS ledger_balance,
    (i.stock_quantity - l.quantity_after) AS drift,
    ((l.quantity_after IS NOT NULL) AND (i.stock_quantity <> l.quantity_after)) AS is_drifted,
    (l.quantity_after IS NULL) AS no_post_cutover_ledger,
    COALESCE(c.post_moves, (0)::bigint) AS post_cutover_movements,
    COALESCE(c.pre_moves, (0)::bigint) AS pre_ledger_movements,
    COALESCE(c.undated_moves, (0)::bigint) AS undated_movements,
    l.created_at AS last_movement_at
   FROM ((public.inventory_items i
     LEFT JOIN latest l ON (((l.inventory_item_id)::text = (i.id)::text)))
     LEFT JOIN counts c ON (((c.inventory_item_id)::text = (i.id)::text)))
  WHERE i.is_active;

CREATE OR REPLACE VIEW public.v_manager_override_summary AS
 SELECT (date_trunc('day'::text, o.created_at))::date AS fecha,
    ua.name AS gerente,
    a.category,
    count(*) AS overrides,
    ((sum(COALESCE(o.value_delta_cents, 0)))::numeric / 100.0) AS valor_removido,
    count(DISTINCT o.requested_by) AS solicitantes,
    count(*) FILTER (WHERE ((o.outcome)::text = 'WARN_ONLY'::text)) AS sin_autorizacion
   FROM ((public.authorization_overrides o
     JOIN public.users ua ON (((ua.id)::text = (o.authorized_by)::text)))
     LEFT JOIN public.authorized_actions a ON (((a.action_code)::text = (o.action_code)::text)))
  GROUP BY ((date_trunc('day'::text, o.created_at))::date), ua.name, a.category
  ORDER BY ((date_trunc('day'::text, o.created_at))::date) DESC, (count(*)) DESC;

CREATE OR REPLACE VIEW public.v_menu_availability AS
 SELECT c.name AS categoria,
    mi.id AS menu_item_id,
    mi.name AS producto,
    mi.price_cents,
    s.max_sellable,
    s.limiting_factor,
    s.limiting_item,
    (s.max_sellable = 0) AS agotado
   FROM ((public.menu_items mi
     LEFT JOIN public.menu_categories c ON (((c.id)::text = (mi.category_id)::text)))
     CROSS JOIN LATERAL public.fn_menu_item_max_sellable(mi.id) s(max_sellable, limiting_factor, limiting_item))
  WHERE (mi.is_active AND mi.tracks_inventory)
  ORDER BY (s.max_sellable = 0) DESC, c.name, mi.name;

CREATE OR REPLACE VIEW public.v_menu_items_without_recipe AS
 SELECT c.name AS categoria,
    mi.id,
    mi.name,
    mi.price_cents,
    ( SELECT count(*) AS count
           FROM public.ticket_line_items li
          WHERE (((li.menu_item_id)::text = (mi.id)::text) AND ((li.status)::text <> 'VOIDED'::text))) AS times_sold,
    (EXISTS ( SELECT 1
           FROM ((public.menu_item_modifier_groups g
             JOIN public.modifiers m ON (((m.modifier_group_id)::text = (g.modifier_group_id)::text)))
             JOIN public.modifier_inventory_rules r ON (((r.modifier_id)::text = (m.id)::text)))
          WHERE (((g.menu_item_id)::text = (mi.id)::text) AND m.is_active))) AS has_modifier_coverage
   FROM (public.menu_items mi
     LEFT JOIN public.menu_categories c ON (((c.id)::text = (mi.category_id)::text)))
  WHERE (mi.is_active AND mi.tracks_inventory AND (NOT (EXISTS ( SELECT 1
           FROM public.insumos_base b
          WHERE ((b.menu_item_id)::text = (mi.id)::text)))))
  ORDER BY ( SELECT count(*) AS count
           FROM public.ticket_line_items li
          WHERE (((li.menu_item_id)::text = (mi.id)::text) AND ((li.status)::text <> 'VOIDED'::text))) DESC;

CREATE OR REPLACE VIEW public.v_modifier_coverage_gaps AS
 SELECT g.name AS group_name,
    m.id AS modifier_id,
    m.name AS modifier_name,
    m.price_cents,
    m.deducts_no_inventory,
    ( SELECT count(*) AS count
           FROM public.line_item_modifiers lm
          WHERE ((lm.modifier_id)::text = (m.id)::text)) AS times_sold
   FROM (public.modifiers m
     JOIN public.modifier_groups g ON (((g.id)::text = (m.modifier_group_id)::text)))
  WHERE (m.is_active AND (NOT m.deducts_no_inventory) AND (NOT (EXISTS ( SELECT 1
           FROM public.modifier_inventory_rules r
          WHERE ((r.modifier_id)::text = (m.id)::text)))))
  ORDER BY ( SELECT count(*) AS count
           FROM public.line_item_modifiers lm
          WHERE ((lm.modifier_id)::text = (m.id)::text)) DESC;

CREATE OR REPLACE VIEW public.v_modifier_groups_unsatisfiable AS
 SELECT g.id,
    g.name,
    g.min_selections,
    g.max_selections,
    g.allow_multiple,
    count(m.id) FILTER (WHERE m.is_active) AS active_options
   FROM (public.modifier_groups g
     LEFT JOIN public.modifiers m ON (((m.modifier_group_id)::text = (g.id)::text)))
  WHERE (EXISTS ( SELECT 1
           FROM (public.menu_item_modifier_groups mg
             JOIN public.menu_items mi ON ((((mi.id)::text = (mg.menu_item_id)::text) AND mi.is_active)))
          WHERE ((mg.modifier_group_id)::text = (g.id)::text)))
  GROUP BY g.id, g.name, g.min_selections, g.max_selections, g.allow_multiple
 HAVING ((count(m.id) FILTER (WHERE m.is_active) = 0) OR ((NOT g.allow_multiple) AND (g.min_selections > count(m.id) FILTER (WHERE m.is_active))));

CREATE OR REPLACE VIEW public.v_pack_lots_open AS
 SELECT l.id,
    i.name AS pack_item,
    l.units_per_pack,
    l.packs_received,
    l.packs_remaining,
    (l.packs_remaining * l.units_per_pack) AS loose_equivalent,
    l.received_at
   FROM (public.inventory_pack_lots l
     JOIN public.inventory_items i ON (((i.id)::text = (l.inventory_item_id)::text)))
  WHERE (l.packs_remaining > (0)::numeric)
  ORDER BY i.name, l.received_at;

CREATE OR REPLACE VIEW public.v_portion_availability AS
 SELECT inventory_items.id,
    inventory_items.name,
    inventory_items.category,
    inventory_items.unit,
    inventory_items.stock_quantity,
    inventory_items.portion_size,
        CASE
            WHEN ((inventory_items.portion_size IS NULL) OR (inventory_items.portion_size = (0)::numeric)) THEN inventory_items.stock_quantity
            ELSE floor((inventory_items.stock_quantity / inventory_items.portion_size))
        END AS portions_available
   FROM public.inventory_items
  WHERE inventory_items.is_active;

CREATE OR REPLACE VIEW public.v_production_variance AS
 SELECT b.batch_number,
    i.name AS producto,
    b.expected_yield,
    b.actual_yield,
    b.variance,
    b.variance_pct,
    b.status,
    u.name AS producido_por,
    (b.started_at)::date AS fecha,
    ((b.input_cost_cents)::numeric / 100.0) AS costo_insumos,
    ((b.output_unit_cost_cents)::numeric / 100.0) AS costo_unitario,
    (b.grant_id IS NOT NULL) AS requirio_autorizacion
   FROM ((public.production_batches b
     JOIN public.inventory_items i ON (((i.id)::text = (b.output_item_id)::text)))
     JOIN public.users u ON (((u.id)::text = (b.produced_by)::text)))
  ORDER BY b.started_at DESC;

CREATE OR REPLACE VIEW public.v_production_yield_trend AS
 SELECT i.name AS producto,
    count(*) AS lotes,
    round(avg(b.variance_pct), 2) AS variacion_promedio_pct,
    round(stddev(b.variance_pct), 2) AS desviacion,
    min(b.variance_pct) AS peor,
    max(b.variance_pct) AS mejor,
    (round(avg(b.output_unit_cost_cents)))::integer AS costo_unitario_promedio
   FROM (public.production_batches b
     JOIN public.inventory_items i ON (((i.id)::text = (b.output_item_id)::text)))
  WHERE ((b.status)::text = 'COMPLETED'::text)
  GROUP BY i.name
 HAVING (count(*) >= 2);

CREATE OR REPLACE VIEW public.v_recipe_coverage AS
 SELECT c.name AS categoria,
    mi.name AS producto,
    mi.price_cents,
    ( SELECT count(*) AS count
           FROM public.insumos_base b
          WHERE ((b.menu_item_id)::text = (mi.id)::text)) AS ingredientes,
    (EXISTS ( SELECT 1
           FROM ((public.menu_item_modifier_groups g
             JOIN public.modifiers m ON (((m.modifier_group_id)::text = (g.modifier_group_id)::text)))
             JOIN public.modifier_inventory_rules r ON (((r.modifier_id)::text = (m.id)::text)))
          WHERE (((g.menu_item_id)::text = (mi.id)::text) AND m.is_active))) AS cubierto_por_modificador,
    ( SELECT count(*) AS count
           FROM public.ticket_line_items li
          WHERE (((li.menu_item_id)::text = (mi.id)::text) AND ((li.status)::text <> 'VOIDED'::text))) AS vendido
   FROM (public.menu_items mi
     LEFT JOIN public.menu_categories c ON (((c.id)::text = (mi.category_id)::text)))
  WHERE (mi.is_active AND mi.tracks_inventory)
  ORDER BY c.name, mi.name;

CREATE OR REPLACE VIEW public.v_recipe_modifier_overlap AS
 SELECT mi.id AS menu_item_id,
    mi.name AS producto,
    ii.name AS insumo,
    b.quantity AS recipe_qty,
    g.name AS grupo,
    m.name AS opcion,
    r.quantity AS modifier_qty
   FROM ((((((public.menu_items mi
     JOIN public.insumos_base b ON (((b.menu_item_id)::text = (mi.id)::text)))
     JOIN public.menu_item_modifier_groups mg ON (((mg.menu_item_id)::text = (mi.id)::text)))
     JOIN public.modifier_groups g ON (((g.id)::text = (mg.modifier_group_id)::text)))
     JOIN public.modifiers m ON ((((m.modifier_group_id)::text = (g.id)::text) AND m.is_active)))
     JOIN public.modifier_inventory_rules r ON ((((r.modifier_id)::text = (m.id)::text) AND ((r.inventory_item_id)::text = (b.inventory_item_id)::text))))
     JOIN public.inventory_items ii ON (((ii.id)::text = (b.inventory_item_id)::text)))
  WHERE mi.is_active;

CREATE OR REPLACE VIEW public.v_shrinkage_summary AS
 SELECT (date_trunc('day'::text, m.created_at))::date AS fecha,
    i.name AS producto,
    i.category,
    sum(m.quantity_delta) FILTER (WHERE ((m.event_type)::text = 'WASTE'::text)) AS merma,
    sum(m.quantity_delta) FILTER (WHERE ((m.event_type)::text = 'COUNT_ADJUSTMENT'::text)) AS ajuste_conteo,
    sum(m.quantity_delta) FILTER (WHERE ((m.event_type)::text = 'MANUAL_ADJUSTMENT'::text)) AS ajuste_manual,
    (sum((m.quantity_delta * (COALESCE(m.unit_cost_cents, 0))::numeric)) / 100.0) AS impacto_costo
   FROM (public.inventory_movements m
     JOIN public.inventory_items i ON (((i.id)::text = (m.inventory_item_id)::text)))
  WHERE (((m.event_type)::text = ANY (ARRAY[('WASTE'::character varying)::text, ('COUNT_ADJUSTMENT'::character varying)::text, ('MANUAL_ADJUSTMENT'::character varying)::text])) AND (m.created_at >= public.ledger_cutover()))
  GROUP BY ((date_trunc('day'::text, m.created_at))::date), i.name, i.category
  ORDER BY ((date_trunc('day'::text, m.created_at))::date) DESC;

CREATE OR REPLACE VIEW public.v_unauthorized_value_reductions AS
 SELECT a.created_at,
    a.action,
    a.entity_type,
    a.entity_id,
    u.name AS actor,
    a.before_state,
    a.after_state,
    a.ip_address
   FROM (public.audit_log a
     LEFT JOIN public.users u ON (((u.id)::text = (a.user_id)::text)))
  WHERE (((a.action)::text = ANY (ARRAY[('ITEM_VOID'::character varying)::text, ('ITEM_QTY_CHANGE'::character varying)::text, ('DISCOUNT_APPLIED'::character varying)::text, ('TICKET_CANCEL'::character varying)::text, ('INVENTORY_ADJUSTMENT'::character varying)::text, ('TIMER_VOID'::character varying)::text, ('TICKET_REOPEN'::character varying)::text])) AND (NOT (EXISTS ( SELECT 1
           FROM public.authorization_overrides o
          WHERE (((o.target_id)::text = (a.entity_id)::text) AND ((o.created_at >= (a.created_at - '00:00:30'::interval)) AND (o.created_at <= (a.created_at + '00:00:30'::interval))))))))
  ORDER BY a.created_at DESC;

CREATE OR REPLACE VIEW public.v_untracked_products AS
 SELECT c.name AS categoria,
    mi.name AS producto,
    ((mi.price_cents)::numeric / 100.0) AS precio,
    mi.untracked_reason,
    ( SELECT count(*) AS count
           FROM public.ticket_line_items li
          WHERE (((li.menu_item_id)::text = (mi.id)::text) AND ((li.status)::text <> 'VOIDED'::text))) AS vendido
   FROM (public.menu_items mi
     LEFT JOIN public.menu_categories c ON (((c.id)::text = (mi.category_id)::text)))
  WHERE (mi.is_active AND (NOT mi.tracks_inventory))
  ORDER BY mi.untracked_reason, ( SELECT count(*) AS count
           FROM public.ticket_line_items li
          WHERE (((li.menu_item_id)::text = (mi.id)::text) AND ((li.status)::text <> 'VOIDED'::text))) DESC;

-- --------------------------------------------------------------------------
-- Indexes (66)
-- --------------------------------------------------------------------------
CREATE INDEX IF NOT EXISTS idx_audit_entity ON public.audit_log USING btree (entity_type, entity_id);

CREATE INDEX IF NOT EXISTS idx_audit_log_action ON public.audit_log USING btree (action, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_audit_log_device ON public.audit_log USING btree (device_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_audit_log_entity ON public.audit_log USING btree (entity_type, entity_id);

CREATE INDEX IF NOT EXISTS idx_auth_grants_authorizer ON public.authorization_grants USING btree (authorized_by, issued_at DESC);

CREATE INDEX IF NOT EXISTS idx_auth_grants_open ON public.authorization_grants USING btree (expires_at) WHERE ((consumed_at IS NULL) AND (revoked_at IS NULL));

CREATE INDEX IF NOT EXISTS idx_auth_grants_target ON public.authorization_grants USING btree (target_type, target_id, issued_at DESC);

CREATE INDEX IF NOT EXISTS idx_auth_overrides_action ON public.authorization_overrides USING btree (action_code, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_auth_overrides_created ON public.authorization_overrides USING btree (created_at DESC);

CREATE INDEX IF NOT EXISTS idx_auth_overrides_manager ON public.authorization_overrides USING btree (authorized_by, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_auth_overrides_target ON public.authorization_overrides USING btree (target_type, target_id);

CREATE INDEX IF NOT EXISTS idx_batches_open ON public.production_batches USING btree (started_at DESC) WHERE ((status)::text = 'OPEN'::text);

CREATE INDEX IF NOT EXISTS idx_batches_output ON public.production_batches USING btree (output_item_id, started_at DESC);

CREATE INDEX IF NOT EXISTS idx_cash_sessions_opened_at ON public.cash_sessions USING btree (opened_at);

CREATE INDEX IF NOT EXISTS idx_conv_from ON public.inventory_conversions USING btree (from_item_id) WHERE is_active;

CREATE INDEX IF NOT EXISTS idx_conv_to ON public.inventory_conversions USING btree (to_item_id) WHERE is_active;

CREATE INDEX IF NOT EXISTS idx_expenses_session ON public.expenses USING btree (session_id);

CREATE INDEX IF NOT EXISTS idx_insumos_base_inventory_item ON public.insumos_base USING btree (inventory_item_id);

CREATE INDEX IF NOT EXISTS idx_inventory_items_base_unit_key ON public.inventory_items USING btree (base_unit_key);

CREATE INDEX IF NOT EXISTS idx_inventory_items_category ON public.inventory_items USING btree (category);

CREATE INDEX IF NOT EXISTS idx_inventory_items_category_name ON public.inventory_items USING btree (category, name);

CREATE INDEX IF NOT EXISTS idx_inventory_items_is_active ON public.inventory_items USING btree (is_active);

CREATE INDEX IF NOT EXISTS idx_inventory_movements_event_type ON public.inventory_movements USING btree (event_type);

CREATE INDEX IF NOT EXISTS idx_inventory_movements_item_created ON public.inventory_movements USING btree (inventory_item_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_inventory_movements_reference_id ON public.inventory_movements USING btree (reference_id) WHERE (reference_id IS NOT NULL);

CREATE INDEX IF NOT EXISTS idx_inventory_movements_restock ON public.inventory_movements USING btree (inventory_item_id, created_at) WHERE ((event_type)::text = 'RESTOCK'::text);

CREATE INDEX IF NOT EXISTS idx_kds_events_replay ON public.kds_events USING btree (destination, sequence);

CREATE INDEX IF NOT EXISTS idx_kds_events_ticket ON public.kds_events USING btree (ticket_id, sequence);

CREATE INDEX IF NOT EXISTS idx_kds_events_unacked ON public.kds_events USING btree (destination, created_at) WHERE (acked_at IS NULL);

CREATE INDEX IF NOT EXISTS idx_ledger_violations_item ON public.ledger_violations USING btree (inventory_item_id, detected_at DESC);

CREATE INDEX IF NOT EXISTS idx_ledger_violations_unresolved ON public.ledger_violations USING btree (detected_at DESC) WHERE (resolved_at IS NULL);

CREATE INDEX IF NOT EXISTS idx_lim_active ON public.line_item_modifiers USING btree (line_item_id) WHERE (voided_at IS NULL);

CREATE INDEX IF NOT EXISTS idx_line_items_kds_pending ON public.ticket_line_items USING btree (ticket_id) WHERE ((quantity <> kds_sent_quantity) AND ((status)::text <> 'VOIDED'::text));

CREATE INDEX IF NOT EXISTS idx_lip_promotion ON public.line_item_promotions USING btree (promotion_id);

CREATE INDEX IF NOT EXISTS idx_lip_ticket ON public.line_item_promotions USING btree (ticket_id);

CREATE INDEX IF NOT EXISTS idx_movements_item_seq ON public.inventory_movements USING btree (inventory_item_id, seq DESC);

CREATE INDEX IF NOT EXISTS idx_pack_lots_fifo ON public.inventory_pack_lots USING btree (inventory_item_id, received_at) WHERE (packs_remaining > (0)::numeric);

CREATE INDEX IF NOT EXISTS idx_pin_attempts_device ON public.pin_attempts USING btree (device_id, attempted_at DESC) WHERE (NOT succeeded);

CREATE INDEX IF NOT EXISTS idx_pin_attempts_recent ON public.pin_attempts USING btree (requested_by, attempted_at DESC);

CREATE INDEX IF NOT EXISTS idx_pts_ticket_endtime ON public.pool_timer_sessions USING btree (ticket_id, end_time);

CREATE INDEX IF NOT EXISTS idx_safe_collections_created ON public.safe_collections USING btree (created_at);

CREATE INDEX IF NOT EXISTS idx_sale_item_costs_inventory_item ON public.sale_item_costs USING btree (inventory_item_id);

CREATE INDEX IF NOT EXISTS idx_sale_item_costs_line_item ON public.sale_item_costs USING btree (ticket_line_item_id);

CREATE INDEX IF NOT EXISTS idx_sale_item_costs_recorded_at ON public.sale_item_costs USING btree (recorded_at);

CREATE INDEX IF NOT EXISTS idx_tickets_closed_at_closed ON public.tickets USING btree (closed_at) WHERE ((status)::text = 'CLOSED'::text);

CREATE INDEX IF NOT EXISTS idx_tickets_closed_by ON public.tickets USING btree (closed_by);

CREATE INDEX IF NOT EXISTS idx_tickets_opened_by ON public.tickets USING btree (opened_by);

CREATE INDEX IF NOT EXISTS idx_tickets_resource_status ON public.tickets USING btree (resource_id, status);

CREATE INDEX IF NOT EXISTS idx_tickets_status ON public.tickets USING btree (status);

CREATE INDEX IF NOT EXISTS idx_tli_ticket_status ON public.ticket_line_items USING btree (ticket_id, status);

CREATE INDEX IF NOT EXISTS idx_tli_voided_at ON public.ticket_line_items USING btree (voided_at) WHERE (voided_at IS NOT NULL);

CREATE INDEX IF NOT EXISTS idx_token_blocklist_created ON public.token_blocklist USING btree (created_at);

CREATE INDEX IF NOT EXISTS idx_wl_status ON public.waiting_list USING btree (status);

CREATE INDEX IF NOT EXISTS ix_line_item_promotions_line_item_id ON public.line_item_promotions USING btree (line_item_id);

CREATE INDEX IF NOT EXISTS ix_line_item_promotions_ticket_id ON public.line_item_promotions USING btree (ticket_id);

CREATE INDEX IF NOT EXISTS ix_promotions_active_type ON public.promotions USING btree (is_active, promo_type);

CREATE INDEX IF NOT EXISTS ix_ticket_promo_decisions_ticket_id ON public.ticket_promo_decisions USING btree (ticket_id);

CREATE UNIQUE INDEX IF NOT EXISTS ix_token_blocklist_jti ON public.token_blocklist USING btree (jti);

CREATE UNIQUE INDEX IF NOT EXISTS sale_item_costs_inventory_movement_id_key ON public.sale_item_costs USING btree (inventory_movement_id);

CREATE UNIQUE INDEX IF NOT EXISTS uq_cash_sessions_open ON public.cash_sessions USING btree (status) WHERE ((status)::text = 'OPEN'::text);

CREATE UNIQUE INDEX IF NOT EXISTS uq_insumos_base_link ON public.insumos_base USING btree (menu_item_id, inventory_item_id);

CREATE UNIQUE INDEX IF NOT EXISTS uq_movements_seq ON public.inventory_movements USING btree (seq);

CREATE UNIQUE INDEX IF NOT EXISTS uq_suppliers_name ON public.suppliers USING btree (lower((name)::text)) WHERE (is_active = true);

CREATE UNIQUE INDEX IF NOT EXISTS uq_tickets_open_per_resource ON public.tickets USING btree (resource_id) WHERE ((status)::text = 'OPEN'::text);

CREATE UNIQUE INDEX IF NOT EXISTS uq_waiting_list_assigned_ticket_active ON public.waiting_list USING btree (assigned_ticket_id) WHERE (((status)::text = ANY (ARRAY[('WAITING'::character varying)::text, ('SEATED'::character varying)::text])) AND (assigned_ticket_id IS NOT NULL));

CREATE UNIQUE INDEX IF NOT EXISTS uq_waiting_list_floor_ticket_active ON public.waiting_list USING btree (floor_ticket_id) WHERE (((status)::text = ANY (ARRAY[('WAITING'::character varying)::text, ('SEATED'::character varying)::text])) AND (floor_ticket_id IS NOT NULL));

