DROP TRIGGER IF EXISTS trg_normalize_name ON public.modifier_groups;
CREATE TRIGGER trg_normalize_name BEFORE INSERT OR UPDATE OF name ON public.modifier_groups FOR EACH ROW EXECUTE FUNCTION public.fn_normalize_name();

DROP TRIGGER IF EXISTS trg_normalize_name ON public.modifiers;
CREATE TRIGGER trg_normalize_name BEFORE INSERT OR UPDATE OF name ON public.modifiers FOR EACH ROW EXECUTE FUNCTION public.fn_normalize_name();

DROP TRIGGER IF EXISTS trg_prevent_negative_stock ON public.inventory_items;
CREATE TRIGGER trg_prevent_negative_stock BEFORE INSERT OR UPDATE OF stock_quantity ON public.inventory_items FOR EACH ROW EXECUTE FUNCTION public.fn_prevent_negative_stock();

DROP TRIGGER IF EXISTS trg_recipe_unit_guard ON public.insumos_base;
CREATE TRIGGER trg_recipe_unit_guard BEFORE INSERT OR UPDATE ON public.insumos_base FOR EACH ROW EXECUTE FUNCTION public.fn_recipe_unit_guard();

-- --------------------------------------------------------------------------
-- Register this baseline. The WHERE NOT EXISTS keeps the row seeded by the
-- guard above intact, and avoids depending on a particular unique constraint.
-- --------------------------------------------------------------------------
INSERT INTO schema_migrations (version, name, notes)
SELECT '001', '001_baseline_squash', 'squashed baseline replacing 027..039'
WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE version = '001');

DO $done$ BEGIN RAISE NOTICE '001_baseline_squash: OK'; END $done$;

COMMIT;
